/* ============================================================
   data.js — single source of truth for the knowledge graph.
   Loaded as a plain <script> (works over file://) so it exposes
   GROUPS, nodes, tree, cross, meta, rootData, ADJ as globals to
   both index.html (the graph) and notes.js (per-page sidebars).

   To add a topic:
     1. add a {id,group,level,desc,link?} entry to `nodes`
     2. add its id to the right domain array in `tree`
     3. (optional) add edges to `cross`  (3rd item "isa" = hierarchy bridge)
   To split a topic into sub-topics (level 3):
     1. add {id,group,level:3,desc,link?} entries to `nodes`
     2. list their ids under the parent topic in `subtree`
     (the parent keeps its own page as the hub/overview)
   To split a sub-topic one level deeper (level 4), do the same:
     add {level:4} entries and key them under the level-3 parent id
     in `subtree` — nesting is recursive, the parent stays the hub.
   Sidebars + the graph update themselves from this file.
   ============================================================ */

const GROUPS = {
  root:  {label:"Data Science", short:"Root", color:"#e6e9ef"},
  math:  {label:"Math & Statistics", short:"Math", color:"#5b9cff"},
  prog:  {label:"Programming & Tools", short:"Programming", color:"#4ade80"},
  dsa:   {label:"Data Structures & Algorithms", short:"DSA", color:"#fb7185"},
  dsys:  {label:"Data Systems", short:"Data Systems", color:"#818cf8"},
  deng:  {label:"Data Engineering", short:"Data Eng", color:"#22d3ee"},
  ml:    {label:"Machine Learning", short:"ML", color:"#ffb454"},
  dl:    {label:"Deep Learning", short:"DL", color:"#f87171"},
  cv:    {label:"Computer Vision", short:"CV", color:"#f472b6"},
  nlp:   {label:"NLP", short:"NLP", color:"#c084fc"},
  mlops: {label:"MLOps & Deployment", short:"MLOps", color:"#a3e635"},
  viz:   {label:"Data Viz & Communication", short:"Data Viz", color:"#fcd34d"},
  llm:   {label:"LLMs & Generative AI", short:"LLMs", color:"#2dd4bf"},
  agent: {label:"Agentic AI", short:"Agentic", color:"#fb923c"},
  speech:{label:"Speech & Audio", short:"Speech", color:"#38bdf8"},
  models:{label:"Model Architectures", short:"Models", color:"#e879f9"},
};

const nodes = [
  {id:"Data Science", group:"root", level:0, desc:"The umbrella field of extracting knowledge and insight from data — spanning the math, engineering, modeling, and communication needed to turn raw data into decisions."},

  // domains
  {id:"Math & Statistics", group:"math", level:1, desc:"The theoretical foundation: the language used to describe data, uncertainty, and learning algorithms."},
  {id:"Programming & Tools", group:"prog", level:1, desc:"The practical toolkit for manipulating data and implementing models at scale."},
  {id:"Data Engineering", group:"deng", level:1, desc:"Building the pipelines and storage that deliver clean, reliable data to models and analysts."},
  {id:"Machine Learning", group:"ml", level:1, desc:"Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed."},
  {id:"Deep Learning", group:"dl", level:1, desc:"Multi-layer neural networks that learn hierarchical representations directly from raw data."},
  {id:"Computer Vision", group:"cv", level:1, desc:"Recovering geometry, motion and meaning from images — the classical pipeline that runs from photons and lenses to features, correspondence and 3D structure. The learned view of vision lives in Deep Learning; this domain owns the geometry and signal processing it is built on."},
  {id:"Classical Vision", group:"cv", level:2, link:"vision/index.html", desc:"Hub page for the classical computer-vision series: the map of the subject, the pipeline that connects the parts, and a cheat sheet. Seven sub-topics below run from image formation to stereo and structure from motion."},
  {id:"Image Formation", group:"cv", level:3, link:"vision/image-formation.html", desc:"How a scene becomes an array of numbers: geometric primitives and 2D/3D transformations, the pinhole camera and projection, intrinsics and extrinsics, lens distortion, photometric formation and light transport, colour, and the sensor pipeline that ends in pixels."},
  {id:"Homogeneous Coordinates & Transformations", group:"cv", level:4, link:"vision/image-formation/homogeneous-transforms.html", desc:"The geometric vocabulary of image formation: 2D points, lines and conics, homogeneous coordinates and the three problems they solve, 3D points, planes, lines and quadrics, the 2D hierarchy from translation through similarity and affine to homography, composition, how lines transform, and the 3D hierarchy."},
  {id:"3D Rotation Parameterisations", group:"cv", level:4, link:"vision/image-formation/rotations.html", desc:"How to represent a 3D rotation: what the nine numbers of a rotation matrix mean, Euler angles and the exact place gimbal lock makes them fail, axis–angle as the minimal parameterisation derived through the exponential map, and unit quaternions with one constraint and no singularity."},
  {id:"The Pinhole Camera & Projection", group:"cv", level:4, link:"vision/image-formation/pinhole-camera.html", desc:"The camera as a projection: orthographic, scaled-orthographic and para-perspective models below perspective, the perspective division and what it costs, the calibration matrix K, focal length against field of view and the units problem, extrinsics and the camera matrix P = K[R|t], and lens distortion with the radius where it stops being invertible."},
  {id:"Optics, Reflectance & Shading", group:"cv", level:4, link:"vision/image-formation/optics-shading.html", desc:"Where pixel values come from: the thin-lens equation, aperture, focus, depth of field and vignetting, radiometric quantities and photometric formation, the BRDF and the reflection equation, and shading from a surface normal to a pixel value and back again."},
  {id:"Colour, Gamma & the Sensor Pipeline", group:"cv", level:4, link:"vision/image-formation/colour-sensor.html", desc:"From spectrum to stored byte: three numbers for an infinite-dimensional spectrum and the colour spaces built on them, gamma encoding as the non-linearity in every loaded image, colour filter arrays and demosaicing, and the sensor with its shot and read noise and the pipeline that ends in eight bits."},
  {id:"Image Processing", group:"cv", level:3, link:"vision/image-processing.html", desc:"Operations on pixels before any interpretation: point operators and histogram equalisation, linear filtering and convolution, separable and Gaussian kernels, non-linear and bilateral filtering, median and rank filters, mathematical morphology, pyramids and multi-resolution, and geometric warping."},
  {id:"Point Operators & Histogram Equalisation", group:"cv", level:4, link:"vision/image-processing/point-operators.html", desc:"Operators that map each pixel through a function of its own value: gain, bias and tone curves with clipping and gamma, the histogram and its cumulative distribution, histogram equalisation and what it actually guarantees, locally adaptive equalisation and CLAHE, and why equalising is often a bad idea."},
  {id:"Linear Filtering & Convolution", group:"cv", level:4, link:"vision/image-processing/linear-filtering.html", desc:"Linear shift-invariant filtering: correlation against convolution and the flipped sign, six padding rules at the border, box, tent, binomial and Gaussian smoothing kernels, separability and its cost, moment conditions for a good filter, derivative filters, the Laplacian and unsharp masking, and band-pass steerable filters."},
  {id:"Non-linear Filters & Morphology", group:"cv", level:4, link:"vision/image-processing/nonlinear-morphology.html", desc:"Neighbourhood operators that are not convolutions: the median and rank filters, the bilateral filter and why it preserves edges, four smoothers compared on one noisy edge, binary morphology filtering by shape, distance transforms with connected components, and integral images giving any rectangle sum in three additions."},
  {id:"Image Pyramids & Multi-Resolution", group:"cv", level:4, link:"vision/image-processing/pyramids.html", desc:"Changing scale: four facts borrowed from the frequency domain, interpolation and decimation with the pre-filter that prevents aliasing, Gaussian and Laplacian pyramids as band-pass decompositions with exact reconstruction, multi-resolution blending across a seam, and wavelets in outline."},
  {id:"Image Warping & Resampling", group:"cv", level:4, link:"vision/image-processing/warping.html", desc:"Geometric transformation of an image: forward against inverse warping and why inverse mapping avoids holes, interpolation kernels from nearest and bilinear through bicubic to windowed sinc, the local resampling rate a warp implies, MIP-maps and anisotropic filtering."},
  {id:"Frequency Domain", group:"cv", level:3, link:"vision/frequency-domain.html", desc:"Images as signals: the Fourier transform and the DFT, the sampling theorem and aliasing, filtering as multiplication in the frequency domain, the convolution theorem, windowing, and the wavelet and DCT transforms that underpin image compression."},
  {id:"The Continuous Fourier Transform", group:"cv", level:4, link:"vision/frequency-domain/fourier-transform.html", desc:"The Fourier transform from the one experiment that defines it, a sinusoid in and a scaled, shifted sinusoid out, then the continuous transform worked out on the rectangular pulse that generates everything else, its properties of shift, modulation, convolution, differentiation and scaling each with a one-line reason, and the transform pairs worth knowing by heart."},
  {id:"The DFT, FFT & 2D Spectra", group:"cv", level:4, link:"vision/frequency-domain/dft-fft.html", desc:"The discrete Fourier transform as a finite, exact, invertible matrix, why its basis diagonalises convolution, the FFT that makes the frequency domain usable at all, reading a two-dimensional image spectrum, and magnitude versus phase, with the phase-swap experiment showing which carries the structure."},
  {id:"Image Sampling & Aliasing", group:"cv", level:4, link:"vision/frequency-domain/sampling-aliasing.html", desc:"Sampling seen in the frequency domain: multiplying by an impulse train replicates the spectrum, the sampling theorem and the sinc reconstruction it promises, aliasing as high frequencies folding back into low ones, and the honest version in which nothing photographed is band-limited and prefiltering is a compromise."},
  {id:"Frequency-Domain Filtering & Windowing", group:"cv", level:4, link:"vision/frequency-domain/filtering-windowing.html", desc:"Filtering as multiplication: the convolution theorem derived, the circular-versus-linear wraparound error and zero padding, filter design as choosing a shape in two domains at once, why the Gaussian is uniquely well behaved, the uncertainty principle, and windowing with its spectral leakage trade-offs."},
  {id:"Gabor, DCT & Wavelet Transforms", group:"cv", level:4, link:"vision/frequency-domain/localised-transforms.html", desc:"Giving up global frequency for local bases: the windowed Fourier transform and Gabor filters, the DCT and why compression prefers it to the DFT, wavelets as multi-resolution analysis, the lifting scheme that builds a wavelet transform without filter design, and the time–frequency tilings that tell these transforms apart."},
  {id:"Features & Matching", group:"cv", level:3, link:"vision/features.html", desc:"Finding what is repeatable: edges and the Canny detector, corners and the Harris response, blob and scale-space detection, invariant descriptors, matching strategies and ratio tests, and robust fitting with RANSAC."},
  {id:"Corner Detection & Harris", group:"cv", level:4, link:"vision/features/corners.html", desc:"Why the aperture problem forces corners, the local autocorrelation surface and its quadratic approximation by the structure tensor, eigenvalue-free corner responses such as Harris and Shi–Tomasi, the full detector with its unwritten details, and adaptive non-maximal suppression for spatially even keypoints."},
  {id:"Edge Detection, Canny & Hough Lines", group:"cv", level:4, link:"vision/features/edges-lines.html", desc:"Edges as gradient-magnitude ridges: Canny's three criteria and four stages, non-maximum suppression along the gradient direction, hysteresis with two thresholds, zero crossings of the Laplacian of Gaussian, linking edge pixels into contours, and finding lines by Hough voting, split-and-merge and sampling."},
  {id:"Scale Space & Blob Detection", group:"cv", level:4, link:"vision/features/scale-space.html", desc:"Detection across scale: the Gaussian scale space and the uniqueness argument behind it, automatic scale selection with σ-normalised derivatives, Laplacian and difference-of-Gaussian blob detectors, finding and pruning extrema in the 3D (x, y, σ) volume, and affine adaptation of the region shape."},
  {id:"Feature Descriptors, Matching & RANSAC", group:"cv", level:4, link:"vision/features/descriptors-matching.html", desc:"From keypoint to verified correspondence: the invariance–discriminability trade-off in descriptor design, dominant-orientation assignment, gradient-histogram and binary descriptors with Hamming matching, the nearest-neighbour ratio test, approximate nearest-neighbour search, and RANSAC model fitting when many matches are outliers."},
  {id:"Segmentation", group:"cv", level:3, link:"vision/segmentation.html", desc:"Partitioning an image into regions: thresholding and Otsu's method, region growing and split-and-merge, watershed, active contours, graph cuts and normalised cuts, mean shift, and superpixels."},
  {id:"Thresholding & Connected Components", group:"cv", level:4, link:"vision/segmentation/thresholding.html", desc:"Segmentation through the one-dimensional keyhole of the histogram: global thresholds, Otsu's method derived with its within-class and between-class criteria shown to be the same, when a histogram is bimodal enough, adaptive local thresholds, and labelling the binary map into connected components."},
  {id:"Region Growing & Watershed", group:"cv", level:4, link:"vision/segmentation/regions-watershed.html", desc:"Region-based segmentation: seeded region growing and the leakage that defines its failure, split-and-merge on a quadtree, the region adjacency graph with an adaptive merge predicate, the watershed transform that floods the gradient image as a landscape, and markers against over-segmentation."},
  {id:"Active Contours & Level Sets", group:"cv", level:4, link:"vision/segmentation/active-contours.html", desc:"Boundaries found by minimising an energy: the parametric snake balancing elastic and bending terms against image forces as it descends into an edge, the four things a snake cannot do, and level sets that evolve an implicit surface so the curve can split and merge."},
  {id:"Mean Shift Segmentation", group:"cv", level:4, link:"vision/segmentation/mean-shift.html", desc:"Segmentation as density mode seeking: pixels as samples from a kernel density estimate in feature space, mean shift as gradient ascent with no explicit gradient and no step size, the role of bandwidth, and the joint spatial-range domain that puts pixel position back into the vector."},
  {id:"Normalised Cuts, Graph Cuts & Superpixels", group:"cv", level:4, link:"vision/segmentation/graph-partitioning.html", desc:"The image as a weighted pixel graph: affinity design, the normalised cut and its generalised eigenvalue relaxation, why the Fiedler vector bisects, exactly optimal binary labelling by s–t min-cut, interactive seeded segmentation, and superpixels as a deliberate over-segmentation for later stages."},
  {id:"Alignment & Motion", group:"cv", level:3, link:"vision/alignment-motion.html", desc:"Putting images into correspondence: parametric motion models, homography estimation, image warping and stitching, optical flow with Lucas-Kanade and Horn-Schunck, the aperture problem, and coarse-to-fine tracking."},
  {id:"Parametric Alignment & the DLT", group:"cv", level:4, link:"vision/alignment-motion/parametric-fitting.html", desc:"Fitting a 2D motion model to point correspondences: the hierarchy from translation to homography and the minimal points each costs, linear least squares for affine motion, closed-form rigid Procrustes via the SVD, the direct linear transform, Hartley normalisation of its conditioning, and nonlinear refinement on geometric error."},
  {id:"Robust Alignment & When Homographies Hold", group:"cv", level:4, link:"vision/alignment-motion/robust-homographies.html", desc:"Alignment with bad matches and the wrong model: RANSAC with a homography inside it, its minimal sample, degeneracies and threshold, bounded-influence M-estimators as the alternative, and the only two cases in which a homography is exact, a plane or a purely rotating camera, with the plane-plus-parallax residual everywhere else."},
  {id:"Image Stitching & Panoramas", group:"cv", level:4, link:"vision/alignment-motion/stitching.html", desc:"Turning pairwise homographies into a panorama: inverse warping and resampling, choosing a flat, cylindrical or spherical compositing surface, the full stitching pipeline, global alignment that closes the loop and removes drift, per-image exposure gains, and seam selection with multi-band blending."},
  {id:"Optical Flow", group:"cv", level:4, link:"vision/alignment-motion/optical-flow.html", desc:"Dense motion from brightness constancy: the linearised constraint and the aperture problem as underdetermination, local Lucas–Kanade least squares, global Horn–Schunck smoothness, coarse-to-fine pyramids for large motion, forward, compositional and inverse-compositional parametric alignment, the occlusion failures, and how flow is evaluated."},
  {id:"Stereo & Structure from Motion", group:"cv", level:3, link:"vision/stereo-sfm.html", desc:"Recovering the third dimension: epipolar geometry and the fundamental matrix, rectification, stereo correspondence and disparity, triangulation, camera calibration, bundle adjustment, and the structure-from-motion pipeline."},
  {id:"Epipolar Geometry", group:"cv", level:4, link:"vision/stereo-sfm/epipolar-geometry.html", desc:"Why two-view correspondence search is one-dimensional: the epipolar plane and the pencil of epipolar lines, where the epipoles sit, the essential matrix from calibrated pose, the fundamental matrix in pixels with distances that measure a violation, and why F has rank 2 and seven degrees of freedom."},
  {id:"Fundamental Matrix Estimation", group:"cv", level:4, link:"vision/stereo-sfm/fundamental-estimation.html", desc:"Estimating F and E from point correspondences: the eight-point algorithm as a null-space problem, coordinate normalisation and the conditioning it buys, enforcing rank 2 by SVD truncation, minimal seven- and five-point solvers, and robust RANSAC estimation with the degenerate configurations no estimator escapes."},
  {id:"Relative Pose & Triangulation", group:"cv", level:4, link:"vision/stereo-sfm/pose-triangulation.html", desc:"From the essential matrix to cameras and points: decomposing E into four candidate rotations and translations, cheirality selecting the one with points in front of both cameras, then triangulation by the mid-point method, the linear DLT, and the optimal two-view method minimising reprojection error."},
  {id:"Dense Stereo Matching", group:"cv", level:4, link:"vision/stereo-sfm/dense-stereo.html", desc:"Dense depth from a calibrated pair: rectification that turns epipolar lines into scanlines, the inverse disparity–depth law and its error growth, matching costs from SAD to NCC and census, the cost volume with winner-take-all, window aggregation, global and semi-global smoothness, sub-pixel refinement and its bias, and the failure modes."},
  {id:"Structure from Motion & Bundle Adjustment", group:"cv", level:4, link:"vision/stereo-sfm/sfm-bundle-adjustment.html", desc:"Reconstruction from many views: the incremental structure-from-motion pipeline, affine factorization recovering shape and motion in one SVD, bundle adjustment as the reprojection objective solved by Levenberg–Marquardt, the arrowhead sparsity and Schur complement, gauge freedom, self-calibration for metric structure, and drift removed by loop closure."},
  {id:"NLP", group:"nlp", level:1, desc:"Natural Language Processing — teaching machines to understand and generate human language."},
  {id:"MLOps & Deployment", group:"mlops", level:1, desc:"The discipline of shipping, serving, and maintaining ML systems reliably in production."},
  {id:"Data Viz & Communication", group:"viz", level:1, desc:"Turning analysis into clear visuals and narratives that drive decisions."},
  {id:"LLMs & Generative AI", group:"llm", level:1, desc:"The modern generative stack built on large pretrained models: prompting and context, parameter-efficient adaptation, preference alignment, evaluation, and multimodal + diffusion variants."},
  {id:"Agentic AI", group:"agent", level:1, desc:"LLMs that plan, use tools, and act over multiple steps to accomplish goals — agents, the skills they wield, how they're trained, and the design patterns that structure them."},
  {id:"Model Architectures", group:"models", level:1, desc:"Landmark models, grouped by modality — vision, NLP, LLM families, audio, multimodal and document AI — each with notes, key research papers, and visuals."},

  // Math & Statistics
  {id:"Linear Algebra", group:"math", level:2, link:"math/linear-algebra.html", desc:"Vectors, matrices, eigen-decompositions — the substrate of nearly every ML computation. Hub page: the map of the subject, split into six sub-topics below."},
  // Linear Algebra sub-topics (level 3) — one page each, in book-chapter order
  {id:"Vectors & Vector Spaces", group:"math", level:3, link:"math/linear-algebra-vectors.html", desc:"Vectors as ordered lists and as arrows; the dot, outer, Hadamard and cross products; span, linear independence, basis, and subspaces — the vocabulary every later topic uses."},
  {id:"Matrices & Rank", group:"math", level:3, link:"math/linear-algebra-matrices.html", desc:"Matrices as data tables and as linear transformations; the matrix zoo, matrix multiplication and its four views, norms, rank, and the four fundamental subspaces (column, row, null, left-null)."},
  {id:"Systems, Determinants & Inverses", group:"math", level:3, link:"math/linear-algebra-systems.html", desc:"Solving Ax = b by row reduction (Gaussian / Gauss-Jordan elimination, RREF), the determinant as a volume-scaling singularity test, and the inverse, one-sided inverses, and the Moore-Penrose pseudoinverse."},
  {id:"Projections & Least-Squares", group:"math", level:3, link:"math/linear-algebra-projections.html", desc:"Projecting a vector onto a line or subspace, orthogonal matrices, Gram-Schmidt and the QR decomposition, and least-squares as the projection of the data onto the column space of the design matrix."},
  {id:"Eigendecomposition & SVD", group:"math", level:3, link:"math/linear-algebra-eigen-svd.html", desc:"Complex numbers, eigenvalues and eigenvectors, diagonalization, symmetric matrices, and the singular value decomposition — rank, subspaces, condition number, pseudoinverse, and low-rank approximation from one factorization."},
  {id:"Quadratic Forms, Covariance & PCA", group:"math", level:3, link:"math/linear-algebra-quadratic-pca.html", desc:"The quadratic form xᵀAx and matrix definiteness, covariance and correlation matrices as Gram matrices of centered data, and PCA as the eigendecomposition of the covariance matrix."},
  {id:"Probability", group:"math", level:2, link:"math/probability/index.html", desc:"The calculus of uncertainty: given a model of a chance experiment, what will the data look like? Hub page: the map of the subject, split into seven sub-topics below — foundations, discrete and continuous distributions, expectation, joint distributions, limit theorems, and simulation & stochastic processes."},
  // Probability sub-topics (level 3) — one page each, in dependency order
  {id:"Probability Foundations", group:"math", level:3, link:"math/probability/foundations.html", desc:"Sample spaces, events and the axioms; counting and combinatorics; conditional probability, the multiplication rule, the law of total probability and Bayes' rule; independence — the grammar every later probability statement is written in."},
  {id:"Random Variables & Discrete Distributions", group:"math", level:3, link:"math/probability/discrete-distributions.html", desc:"A random variable as a number attached to an outcome: PMF and CDF, and the discrete zoo — Bernoulli, binomial, geometric, negative binomial, hypergeometric and Poisson — with the stories that generate them and the Poisson approximation to the binomial."},
  {id:"PMFs, CDFs & Expected Value", group:"math", level:4, link:"math/probability/discrete-distributions/pmf-cdf-expectation.html", desc:"How a discrete distribution is described and summarised: the probability mass function and cumulative distribution function, reading one from the other, quantiles as the cdf read backwards, the distribution of a function of X, the expected value as balance point and when it fails to exist, and variance as typical distance from the mean."},
  {id:"Binomial, Geometric & Hypergeometric Distributions", group:"math", level:4, link:"math/probability/discrete-distributions/bernoulli-trials.html", desc:"Families built from Bernoulli trials: the Bernoulli and binary cross-entropy, the binomial pmf derived with its mean, variance and tails, the memoryless geometric and the coupon collector, the negative binomial and overdispersion, and the hypergeometric for draws without replacement with its finite-population correction and capture–recapture."},
  {id:"The Poisson & Multinomial Distributions", group:"math", level:4, link:"math/probability/discrete-distributions/poisson-multinomial.html", desc:"The Poisson as the law of rare events, derived from the binomial, with rates, windows and sums and where it fails, the total-variation bound on the binomial-to-Poisson gap and how both lead to the normal curve, then the categorical distribution and multinomial counts that classification runs on."},
  {id:"Continuous Distributions", group:"math", level:3, link:"math/probability/continuous-distributions.html", desc:"Densities and why P(X = x) = 0: pdf, cdf and quantiles; uniform, exponential and memorylessness, normal, gamma, beta, Pareto and lognormal; transforming a single random variable, and the family tree that relates the distributions."},
  {id:"Densities, the Uniform & the Exponential", group:"math", level:4, link:"math/probability/continuous-distributions/densities-uniform-exponential.html", desc:"Working with densities: normalising constants and support, mean and variance by integration, the quantile function and mixed distributions, then the uniform as the atom every simulation is built from, and the exponential as the Poisson waiting time, memoryless in both directions, with hazard rates, competing exponentials and the geometric limit."},
  {id:"The Gamma, Normal & Beta Families", group:"math", level:4, link:"math/probability/continuous-distributions/gamma-normal-beta.html", desc:"The workhorse continuous families: the gamma function and the gamma as the waiting time for the r-th arrival, the gamma–Poisson mixture and chi-square, the normal with its σ√(2π) constant, standardising and the 68–95–99.7 rule, and the beta with pseudo-counts, conjugate updating and an order-statistic preview."},
  {id:"Heavy Tails & Transforming a Random Variable", group:"math", level:4, link:"math/probability/continuous-distributions/heavy-tails-transforms.html", desc:"Heavy tails through the Pareto power law and the lognormal, three tails with the same mean and why sample means mislead under them, then transforming a random variable by the cdf method and the change-of-variables formula, the non-monotone case, and the probability integral transform in both directions."},
  {id:"Expectation, Variance & Inequalities", group:"math", level:3, link:"math/probability/expectation.html", desc:"What a random quantity does on average and how far it strays: expectation and LOTUS, variance and moments, moment generating functions, the tail bounds (Markov, Chebyshev, Jensen, Chernoff-Hoeffding), and conditional expectation with the tower rule."},
  {id:"LOTUS, Linearity & Variance", group:"math", level:4, link:"math/probability/expectation/lotus-linearity-variance.html", desc:"The rules expectation runs on: LOTUS proved by regrouping and why E g(X) is not g(E X), linearity with no independence needed and its killer application to indicators, why E XY does need independence, variance and its rules, the mean as best constant guess, and skewness and kurtosis of the families."},
  {id:"Moment Generating Functions & Tail Bounds", group:"math", level:4, link:"math/probability/expectation/mgf-tail-bounds.html", desc:"The moment generating function as a package of all moments, mgfs multiplying for independent sums and the closure results that follow, the lognormal mean, cumulants and where mgfs fail, then the first tail bounds from moments alone: Markov, Chebyshev with the weak law in one line, and Cantelli's one-sided inequality."},
  {id:"Jensen, Hoeffding & Generalisation Bounds", group:"math", level:4, link:"math/probability/expectation/concentration.html", desc:"Inequalities that do more than moments: Jensen's inequality and E log ≤ log E behind variational bounds, Cauchy–Schwarz, the Chernoff method, Hoeffding's lemma and the sub-Gaussian idea, Hoeffding's inequality, and concentration in action as a three-step generalisation bound with real numbers and honest caveats."},
  {id:"Conditional Expectation & Total Variance", group:"math", level:4, link:"math/probability/expectation/conditional-expectation.html", desc:"Conditional expectation as a number and as a random variable, the tower rule and its working rules, the conditional mean as the best mean-squared predictor, and the law of total variance proved and applied to hierarchical models such as the negative binomial's μ + μ²/r, ending at the bridge to the analysis of variance."},
  {id:"Joint Distributions & Dependence", group:"math", level:3, link:"math/probability/joint-distributions.html", desc:"Several random variables at once: joint, marginal and conditional distributions, independence, covariance and correlation, sums and convolution, the bivariate and multivariate normal, change of variables with Jacobians, order statistics and mixtures."},
  {id:"Independence, Covariance & Conditional Distributions", group:"math", level:4, link:"math/probability/joint-distributions/dependence.html", desc:"How two variables depend on each other: three equivalent definitions of independence and the iid atom, covariance with its product-like rules and the variance of a sum, the covariance matrix, correlation with |ρ| ≤ 1 proved and its linear-only reach, and conditional distributions as renormalised slices with Bayes' rule for densities."},
  {id:"Convolution, Jacobians & Order Statistics", group:"math", level:4, link:"math/probability/joint-distributions/transformations.html", desc:"Distributions of functions of several random variables: sums by discrete and continuous convolution with Poisson and gamma closure, the Jacobian change-of-variables theorem with the polar trick and Box–Muller, the beta–gamma identity, and order statistics from the extremes to the k-th of n uniforms being Beta(k, n − k + 1)."},
  {id:"The Multivariate Normal & Mixtures", group:"math", level:4, link:"math/probability/joint-distributions/multivariate-normal.html", desc:"The multivariate normal built from independent standard normals, closed under linear maps, where zero covariance means independence and conditionals are normal with exactly linear means, giving regression to the mean and Mahalanobis distance; then mixtures, hierarchical models as chains of conditionals, and the Dirichlet distribution."},
  {id:"Limit Theorems & Convergence", group:"math", level:3, link:"math/probability/limit-theorems.html", desc:"What happens as n grows: the modes of convergence and how they relate, the weak and strong laws of large numbers, the central limit theorem and a proof sketch, the delta method, Slutsky's theorem and the continuous mapping theorem."},
  {id:"Modes of Convergence & the Laws of Large Numbers", group:"math", level:4, link:"math/probability/limit-theorems/laws-of-large-numbers.html", desc:"How the four modes of convergence relate, with the implications proved, the counterexamples worked and the partial converses, then the weak law from Chebyshev and Khinchin's finite-mean version, Borel–Cantelli, a four-moment proof of the strong law, why a finite mean is necessary, and the gambler's fallacy made rigorous."},
  {id:"The Central Limit Theorem", group:"math", level:4, link:"math/probability/limit-theorems/central-limit-theorem.html", desc:"The central limit theorem stated and proved by cumulants, the convolution view of why the limit is normal, what convergence in distribution buys, the Berry–Esseen rate, stable laws when variance is infinite, Lindeberg–Feller for non-identical terms, and normal approximations to binomial, Poisson and gamma with Edgeworth error and the continuity correction."},
  {id:"The Delta Method & Slutsky's Theorem", group:"math", level:4, link:"math/probability/limit-theorems/delta-slutsky.html", desc:"Carrying limits through functions: the delta method proved and worked on three functions of means, what it does not promise, variance-stabilising transforms, then Slutsky's theorem and continuous mapping, the tempting wrong generalisation, and the t statistic assembled from these pieces."},
  {id:"Sample Quantiles & Extreme Values", group:"math", level:4, link:"math/probability/limit-theorems/quantiles-extremes.html", desc:"Limits for order statistics: sample quantiles are asymptotically normal with variance set by the density at the quantile, worked for the exponential median and hard where the density is flat, while the maximum follows one of three extreme-value limits, with the exponential maximum shown to be Gumbel."},
  {id:"Simulation & Stochastic Processes", group:"math", level:3, link:"math/probability/stochastic-processes.html", desc:"Making randomness computable, then letting it evolve in time: pseudo-random numbers, inverse-transform and rejection sampling, Monte Carlo estimation and its 1/√n error, Markov chains and stationary distributions, and the Bernoulli and Poisson processes."},
  {id:"Sampling Random Variates", group:"math", level:4, link:"math/probability/stochastic-processes/sampling-variates.html", desc:"Turning U(0, 1) draws into any distribution: the inverse transform for discrete tables and continuous cdfs, rejection sampling proved and seen as points under a curve, the squeeze, polar and ziggurat normals, why rejection dies in high dimension, and the zoo from gammas and Cholesky normals to the alias method."},
  {id:"Monte Carlo Estimation & Variance Reduction", group:"math", level:4, link:"math/probability/stochastic-processes/monte-carlo.html", desc:"Estimating an expectation by averaging draws: the Monte Carlo estimator with its consistency and 1/√N error bar, where it beats quadrature, and the variance-reduction toolkit of antithetic variates, control variates, stratification, importance sampling and common random numbers, each with the variance it removes."},
  {id:"Poisson Processes & Markov Chains", group:"math", level:4, link:"math/probability/stochastic-processes/poisson-markov.html", desc:"Randomness evolving in time: the Bernoulli process and its continuous-time limit the Poisson process, count–time duality, superposition, thinning and the inspection paradox, then Markov chains with transition matrices, Chapman–Kolmogorov, state classification, stationary distributions, convergence, detailed balance and absorbing chains."},
  {id:"Ergodic Averages, MCMC & Queues", group:"math", level:4, link:"math/probability/stochastic-processes/ergodic-mcmc-queues.html", desc:"What a long Markov-chain run delivers: the ergodic theorem and Markov-chain CLT with integrated autocorrelation time and effective sample size, Metropolis–Hastings and Gibbs sampling with honest mixing diagnostics, and the M/M/1 queue whose geometric stationary law and Little's law explain blow-up near ρ = 1."},
  {id:"Fourier Analysis", group:"math", level:2, link:"math/fourier-analysis.html", desc:"Decomposing functions into sinusoids: Fourier series and their convergence, the function-space view where coefficients are projections, Parseval, the transform and convolution, and the statistical side — periodograms, spectral density, and the characteristic function as the Fourier transform of a distribution."},
  {id:"Fourier Series", group:"math", level:3, link:"math/fourier-analysis/fourier-series.html", desc:"Building the Fourier series: sinusoids in amplitude–phase and cosine–sine form, Euler's formula and why complex exponentials win the bookkeeping, functions as vectors under an inner product with orthogonality proved, coefficients as projections and truncations as best approximations, then the definitions, symmetry shortcuts and the square wave and sawtooth worked."},
  {id:"Convergence, Term-by-Term Calculus & Parseval", group:"math", level:3, link:"math/fourier-analysis/convergence-parseval.html", desc:"When a Fourier series converges and in what sense: why continuity is not enough, Dirichlet's pointwise theorem, the Gibbs overshoot that never dies, uniform and mean-square convergence, smoothness controlling coefficient decay, term-by-term integration and differentiation with the heat equation, and Parseval's theorem giving Σ 1/n² = π²/6 and truncation error as tail energy."},
  {id:"The Fourier Transform & Convolution Theorem", group:"math", level:3, link:"math/fourier-analysis/transform-convolution.html", desc:"The Fourier transform as the period-to-infinity limit of the series, when it exists, why sampling the transform periodises the function, duality between the domains and the uncertainty principle stated honestly, then convolution read three ways and the convolution theorem proved and used to do three convolutions by multiplication."},
  {id:"Characteristic Functions & Spectral Analysis", group:"math", level:3, link:"math/fourier-analysis/characteristic-spectral.html", desc:"The Fourier transform applied to randomness: characteristic functions that exist for every distribution unlike the mgf, their properties, catalogue, uniqueness and inversion, why averaging Cauchy draws never helps, Lévy's continuity theorem and the CLT, then stationary time series with spectral densities and the periodogram that never settles."},
  {id:"Statistics", group:"math", level:2, link:"math/statistics/index.html", desc:"Reasoning from a sample to the population it came from. Hub page: the map of the subject, split into nine sub-topics below — description, design, sampling distributions, estimation, testing, regression, resampling, categorical data, and ANOVA."},
  // Statistics sub-topics (level 3) — one page each, in course order
  {id:"Descriptive Statistics", group:"math", level:3, link:"math/statistics/descriptive.html", desc:"Summarising a batch of numbers before modelling it: histograms and shape, the mean/median/mode trio and when each lies, spread by SD, IQR and MAD, quartiles and boxplots, z-scores and standardisation, outliers, and the plots that reveal what a summary statistic hides."},
  {id:"Producing Data & Sampling", group:"math", level:3, link:"math/statistics/sampling-design.html", desc:"Where the numbers come from decides what they can prove: population vs sample, simple random / stratified / cluster designs, sampling and non-sampling bias, observational study vs randomised experiment, confounding, blinding, and why randomisation is what licenses a causal claim."},
  {id:"Sampling Distributions & CLT", group:"math", level:3, link:"math/statistics/sampling-distributions.html", desc:"The distribution of a statistic across hypothetical repeated samples: parameter vs statistic, the sampling distribution of the mean and of a proportion, the law of large numbers, the central limit theorem and its 1/√n standard error — the result every confidence interval and test rests on."},
  {id:"Estimation & Confidence Intervals", group:"math", level:3, link:"math/statistics/estimation.html", desc:"Turning a point estimate into an interval: standard error, the z and t intervals, what '95% confident' does and does not mean, margin of error and sample-size planning, intervals for proportions, and the bias-variance and coverage properties of an estimator."},
  {id:"Point Estimation: Bias, MSE & Efficiency", group:"math", level:4, link:"math/statistics/estimation/point-estimation.html", desc:"Judging and building point estimators: the bias-variance identity for MSE, when a biased shrinkage estimator beats an unbiased one, Fisher information and the Cramér–Rao bound on efficiency, and three recipes, plug-in, method of moments and maximum likelihood, worked end to end on exponential lifetimes."},
  {id:"Confidence Intervals & the t Distribution", group:"math", level:4, link:"math/statistics/estimation/confidence-intervals.html", desc:"From a point estimate to an interval through a pivotal quantity, what the 95% in a confidence interval actually claims and the four readings that are wrong, and the t interval for when σ is unknown, with where the t distribution and its degrees of freedom come from."},
  {id:"Proportion Intervals & Sample-Size Planning", group:"math", level:4, link:"math/statistics/estimation/proportions-planning.html", desc:"Intervals you will actually build: why the Wald interval for a proportion fails and the Wilson and Clopper–Pearson alternatives, margin of error and planning the sample size, one-sided intervals, differences of means and proportions, a chi-square interval for a variance, and the bootstrap interval in outline."},
  {id:"Hypothesis Testing", group:"math", level:3, link:"math/statistics/hypothesis-testing.html", desc:"The logic of a significance test: null and alternative, the test statistic and its null distribution, p-values and what they are not, one- vs two-sided, type I and II error, power and sample size, the duality with confidence intervals, and the replication-crisis critique."},
  {id:"p-Values & Significance", group:"math", level:4, link:"math/statistics/hypothesis-testing/p-values.html", desc:"From hypotheses to a p-value: choosing H₀ and H₁ and where the burden of proof sits, the test statistic with its null distribution and rejection region, the p-value defined three ways, seven things it is not, and the base-rate arithmetic showing why most significant results can be false."},
  {id:"Power & Error Trade-offs", group:"math", level:4, link:"math/statistics/hypothesis-testing/errors-power.html", desc:"The two ways a test is wrong and the power function that measures both, what drives power and how to plan sample size for it, why post-hoc observed power is empty, and the duality that makes a confidence interval exactly the set of null values a test would not reject."},
  {id:"Standard Tests & the Likelihood Ratio", group:"math", level:4, link:"math/statistics/hypothesis-testing/tests-theory.html", desc:"The tests you will actually run, with the assumption that breaks each: z and t for one mean, paired versus two-sample, Welch versus pooled, the sign test and proportions, then where they come from, the Neyman–Pearson lemma, most powerful tests and the likelihood-ratio test with Wilks' theorem."},
  {id:"Regression & Correlation", group:"math", level:3, link:"math/statistics/regression.html", desc:"The inferential view of the fitted line: correlation and its traps, the regression effect and the fallacy named after it, inference on the slope, residual diagnostics, prediction vs confidence bands, extrapolation, and why r² is not a licence to claim causation."},
  {id:"Correlation & What r Measures", group:"math", level:4, link:"math/statistics/regression/correlation.html", desc:"Describing two quantitative variables: reading a scatterplot for direction, form and strength, the correlation coefficient defined four equivalent ways, the curved and clustered patterns r cannot see, the four explanations of any association besides causation, and how restricted range, outliers and ecological aggregation distort r."},
  {id:"Least-Squares Lines & Regression to the Mean", group:"math", level:4, link:"math/statistics/regression/least-squares-line.html", desc:"The least-squares line derived from its criterion, regression to the mean and the fallacy named after it, the two regression lines and the SD line that is neither, the normal approximation within a vertical strip, and R² = r² as an exact split of the variance."},
  {id:"Inference on the Regression Line", group:"math", level:4, link:"math/statistics/regression/inference-diagnostics.html", desc:"The regression line as a probability model, with what each assumption is holding up: standard error, t test and interval for the slope and the F that repeats them, confidence versus prediction bands, residual plots and transformations, and outliers, leverage and Cook's distance for influential points."},
  {id:"Resampling (Bootstrap & Permutation)", group:"math", level:3, link:"math/statistics/resampling.html", desc:"Replacing distributional assumptions with computation: the bootstrap for standard errors and intervals, permutation tests for comparing groups, when resampling works and when it fails, and the connection to cross-validation."},
  {id:"The Bootstrap & the Plug-In Principle", group:"math", level:4, link:"math/statistics/resampling/bootstrap.html", desc:"The bootstrap built from two ideas: Monte Carlo averaging of random draws and the plug-in principle that puts the empirical distribution where the population should go, the resampling recipe, what one resample contains and where 0.632 comes from, and the nonparametric, parametric, smoothed and block variants."},
  {id:"Bootstrap Confidence Intervals", group:"math", level:4, link:"math/statistics/resampling/bootstrap-intervals.html", desc:"Turning bootstrap replicates into confidence intervals: the normal, percentile and pivotal intervals and why they disagree on skewed data, their actual coverage measured by simulation, the bootstrap-t and BCa intervals that correct it, and choosing B when only Monte Carlo error is yours to shrink."},
  {id:"Permutation & Exact Tests", group:"math", level:4, link:"math/statistics/resampling/permutation-tests.html", desc:"Building a null distribution instead of looking one up: permutation tests by shuffling labels, the exchangeability null they actually test and the claim write-ups get wrong, exact tests by full enumeration with the classical rank tests unmasked as permutation tests, and how permutation differs from bootstrap."},
  {id:"Bootstrap Regression, Failures & the Jackknife", group:"math", level:4, link:"math/statistics/resampling/regression-limits-jackknife.html", desc:"Resampling a regression by residuals, by cases or with the wild bootstrap and which one to trust, five ways the bootstrap fails silently, including extremes and heavy tails, with the damage measured, and the jackknife as the leave-one-out predecessor whose leave-one-out values are the regression influence calculation in disguise."},
  {id:"Categorical Data & Chi-Square", group:"math", level:3, link:"math/statistics/categorical.html", desc:"Counts rather than measurements: two-way tables, conditional distributions, the chi-square tests of goodness-of-fit and independence, expected counts and residuals, odds ratios and relative risk, and Simpson's paradox."},
  {id:"Chi-Square Tests for Tables", group:"math", level:4, link:"math/statistics/categorical/chi-square-tests.html", desc:"Counts in a two-way table read through row, column and joint percentages, expected counts derived from row × column / n, Pearson's chi-square statistic worked through a goodness-of-fit test, degrees of freedom counted not recalled, and homogeneity versus independence kept distinct, with a live table laboratory."},
  {id:"Residuals, Fisher's Exact & McNemar", group:"math", level:4, link:"math/statistics/categorical/exact-paired-residuals.html", desc:"What follows a chi-square result: standardised and adjusted residuals to find the cells that drove it, the expected-count condition measured and Yates' correction, Fisher's exact test as a hypergeometric permutation test, the identities with z² and the likelihood-ratio G, and McNemar's test on paired discordant counts."},
  {id:"Odds Ratios, Study Design & Simpson's Paradox", group:"math", level:4, link:"math/statistics/categorical/effect-measures.html", desc:"How big a categorical association is: risk difference, relative risk and the odds ratio compared, a log-scale interval for the odds ratio and what it covers, which measure a cohort or case-control design lets you compute at all, and Simpson's paradox reversing every subgroup in the pooled table."},
  {id:"ANOVA & Multiple Comparisons", group:"math", level:3, link:"math/statistics/anova.html", desc:"Comparing several groups at once: the F test as a ratio of between- to within-group variance, its assumptions, and then the multiplicity problem — data snooping, family-wise error, Bonferroni and Tukey, and false discovery rate control."},
  {id:"The F Test & One-Way ANOVA", group:"math", level:4, link:"math/statistics/anova/f-test.html", desc:"Why k groups need one test rather than all pairwise t tests: the family-wise inflation measured, total variation split into between and within sums of squares, degrees of freedom and mean squares, the F ratio as two independent chi-squares, an audited ANOVA table, and the square-root law boxplots hide."},
  {id:"The ANOVA Model, Effect Size & Power", group:"math", level:4, link:"math/statistics/anova/model-effect-power.html", desc:"The model behind the table in its cell-means and effects forms, how much normality and equal variance actually matter when measured by simulation, one-way ANOVA as regression on k − 1 indicators, effect sizes η², ω² and Cohen's f that the F refuses to report, and power-based sample-size planning."},
  {id:"Welch, Kruskal–Wallis & the Permutation F", group:"math", level:4, link:"math/statistics/anova/robust-alternatives.html", desc:"Alternatives for when the classical F assumptions fail: the permutation F that needs only exchangeability under the null, Levene and Brown–Forsythe checks for unequal spread, Welch's heteroscedastic ANOVA, and Kruskal–Wallis as the F test run on ranks, with what each one actually tests."},
  {id:"Multiple Comparisons & Error Rates", group:"math", level:4, link:"math/statistics/anova/multiple-comparisons.html", desc:"What to do after a significant F: the multiple-testing fallacy and the look-elsewhere effect, family-wise control by Bonferroni, Šidák and Holm, Tukey's HSD from the studentised range, contrasts with Scheffé's bound as the heart of multiplicity, and the false discovery rate with Benjamini–Hochberg as a different target."},
  {id:"Calculus", group:"math", level:2, link:"math/calculus.html", desc:"Limits, derivatives, Taylor expansion, series, integrals, and matrix differentials — the engine behind optimization and backpropagation."},
  {id:"Optimization", group:"math", level:2, link:"math/optimization.html", desc:"Finding parameters that minimize loss: gradient descent, convexity, momentum, Adam."},

  // Programming & Tools
  {id:"Python", group:"prog", level:2, link:"programming/python.html", desc:"The lingua franca of data science — rich ecosystem of ML and data libraries."},
  {id:"SQL", group:"prog", level:2, link:"programming/sql.html", desc:"Querying and aggregating structured data from relational databases."},
  {id:"Pandas & NumPy", group:"prog", level:2, link:"programming/pandas-numpy.html", desc:"Vectorized arrays and dataframes for in-memory data manipulation. Hub page: why whole-array thinking wins and the shared performance ladder; the two libraries are sub-topics."},
  {id:"NumPy", group:"prog", level:3, link:"programming/numpy.html", desc:"The ndarray memory model — shape, dtype, strides, views vs copies, broadcasting, and axis reductions — the mental model every array library since has copied."},
  {id:"Pandas", group:"prog", level:3, link:"programming/pandas.html", desc:"Labelled, aligned tables on top of NumPy: Series/DataFrame and the Index, dtypes and Copy-on-Write, groupby (split-apply-combine), merge/join/concat, wide↔long reshaping, and missing data."},
  {id:"Git & Version Control", group:"prog", level:2, link:"programming/git.html", desc:"Tracking the history of a project as a directed acyclic graph of immutable snapshots: the content-addressed object model, HEAD/branch/index/working-tree, branching and three-way merge vs rebase, bisect as binary search over history, and the data-science caveats — notebooks that diff badly, data too large to commit, and what reproducibility actually requires."},
  {id:"Git Object Model", group:"prog", level:3, link:"programming/git/object-model.html", desc:"The content-addressed store underneath every command: blobs, trees, commits and tags as an immutable DAG, and the four moving pointers — HEAD, branch, index, working tree — whose positions explain almost every confusing git state."},
  {id:"Recording & Branching", group:"prog", level:3, link:"programming/git/recording-branching.html", desc:"The everyday cycle done well: staging and committing coherent snapshots, ignoring what should never be tracked, cheap branches as movable pointers, and three-way merge — fast-forward, true merges, and what a conflict actually is."},
  {id:"Rebase, Undo & History Search", group:"prog", level:3, link:"programming/git/rewriting-recovering.html", desc:"Operations on history itself: rebase as replay and when not to use it, the safety ladder of checkout, restore, reset, revert and the reflog, and searching history — log pickaxe, blame, and bisect as binary search over commits."},
  {id:"Git Collaboration & Data Science", group:"prog", level:3, link:"programming/git/collaboration-ds.html", desc:"Working with others and with data: remotes and the fetch/push contract, the branching workflows that scale to teams, why notebooks diff badly and data does not belong in commits, DVC and LFS, and the internals in practice — packfiles, GC and what a clone copies."},
  {id:"R", group:"prog", level:2, desc:"A statistics-first language strong in inference and visualization."},
  {id:"Apache Spark", group:"prog", level:2, desc:"Distributed computation for datasets too large for one machine."},
  {id:"Data Structures & Algorithms", group:"dsa", level:1, link:"dsa/data-structures-algorithms.html", desc:"The CS core: arrays, trees, graphs, sorting/searching, dynamic programming, and Big-O complexity analysis."},
  {id:"Data Systems", group:"dsys", level:1, desc:"The infrastructure data lives in: relational and NoSQL stores, indexing and transactions, distributed storage and compute, streaming, lakes and warehouses, and the scaling patterns (caching, queues, load balancing, CAP) that hold it together at volume."},
  // DSA — two level-2 series, each a hub with level-3 parts
  {id:"Data Structures", group:"dsa", level:2, link:"dsa/data-structures/index.html", desc:"How data is arranged in memory, and what that arrangement makes cheap. Seven parts: contiguous arrays and strings, linked nodes, hash tables, heaps, search trees, balanced and multiway trees, and graphs — each an abstract data type with a cost contract attached."},
  {id:"Algorithm Design & Analysis", group:"dsa", level:2, link:"dsa/algorithms/index.html", desc:"How to build a procedure and prove what it costs. Eleven parts: asymptotic analysis and recurrences, recursion and divide-and-conquer, sorting and searching, greedy methods, dynamic programming, graph algorithms, the boundary where efficient algorithms stop existing, and four selected topics — computational geometry, parallel algorithms, online and randomized algorithms, and number-theoretic algorithms."},

  // Data Structures — parts 1-7
  {id:"Arrays & Strings", group:"dsa", level:3, link:"dsa/data-structures/arrays-strings.html", desc:"Contiguous indexed storage: the memory model, index arithmetic, dynamic-array growth and its amortized O(1) append, row-major layout and locality, the two-pointer and sliding-window patterns, prefix sums, and string matching (naive, Rabin-Karp, KMP, Boyer-Moore)."},
  {id:"Array Memory Layout & Dynamic Arrays", group:"dsa", level:4, link:"dsa/data-structures/arrays-strings/memory-dynamic-arrays.html", desc:"Why indexing is O(1): the memory model and address arithmetic, the sequence ADT versus its implementation, referential (boxed, pointer) versus compact arrays, access versus update costs, and dynamic arrays whose geometric growth makes append amortized O(1) — with the 2 versus 1.5 growth-factor trade-off."},
  {id:"Multidimensional Arrays, Locality & Strings", group:"dsa", level:4, link:"dsa/data-structures/arrays-strings/multidim-locality-strings.html", desc:"How layout decides speed: multidimensional arrays flattened row- or column-major with strides, traversal order against cache lines, slices as views that alias rather than copy, and strings as compact, usually immutable arrays of encoded character codes."},
  {id:"Two Pointers, Sliding Window & Prefix Sums", group:"dsa", level:4, link:"dsa/data-structures/arrays-strings/array-techniques.html", desc:"The invariant-driven index patterns that turn quadratic scans linear: converging two pointers, fixed and variable sliding windows with a monotone deque, prefix sums and difference arrays for O(1) range queries, in-place reversal and partitioning, and binary search on a sorted array."},
  {id:"Exact String Matching", group:"dsa", level:4, link:"dsa/data-structures/arrays-strings/string-matching.html", desc:"Finding a pattern of length m in a text of length n: the naive O(nm) scan, Rabin-Karp's rolling hash and spurious hits, KMP's prefix function for worst-case O(n + m), Boyer-Moore's bad-character and good-suffix shifts that run sublinear in practice, and the matchers compared head to head."},
  {id:"String Automata, Regex & Suffix Arrays", group:"dsa", level:4, link:"dsa/data-structures/arrays-strings/automata-regex-suffix.html", desc:"The matching automaton as a DFA, regular expressions via Thompson's NFA versus catastrophic backtracking, where regular languages end and context-free parsing begins, lossless compression with run-length, Huffman and LZ77/LZW plus the counting argument that limits them, and suffix arrays with LCP for indexed search."},
  {id:"Linked Lists, Stacks & Queues", group:"dsa", level:3, link:"dsa/data-structures/linked-stacks-queues.html", desc:"Data held in nodes joined by references, and the three restricted-access ADTs built on top: singly, doubly and circular lists; the stack (LIFO) and the call stack it models; the queue and deque (FIFO); array-backed vs node-backed implementations and the cost each one buys."},
  {id:"Singly & Doubly Linked Lists", group:"dsa", level:4, link:"dsa/data-structures/linked-stacks-queues/singly-doubly-linked.html", desc:"The cost contract of linked storage — O(1) splice, Θ(n) access — and the cache reality of pointer chasing, singly linked lists with a tail pointer, the predecessor problem that makes deletion awkward, doubly linked lists with prev links as its fix, and sentinel nodes that erase the edge cases."},
  {id:"Circular Lists, Runners & Cycle Detection", group:"dsa", level:4, link:"dsa/data-structures/linked-stacks-queues/list-techniques.html", desc:"The pointer-manipulation toolkit: circular lists for round-robin and Josephus-style rotation, the runner technique for middles and k-th-from-end, Floyd's and Brent's cycle detection with their proofs, iterative and recursive reversal, and the positional list ADT that hides nodes behind stable positions."},
  {id:"Stacks & Expression Evaluation", group:"dsa", level:4, link:"dsa/data-structures/linked-stacks-queues/stacks-expressions.html", desc:"The LIFO discipline: the stack ADT and its array-backed versus node-backed implementations, the call stack and its frames, matching balanced delimiters, evaluating postfix expressions, converting infix to postfix with precedence and associativity, and stack applications from undo to backtracking and monotonic stacks."},
  {id:"Queues, Ring Buffers & Deques", group:"dsa", level:4, link:"dsa/data-structures/linked-stacks-queues/queues-ring-buffers.html", desc:"The FIFO discipline: the queue ADT, why a naive array queue drifts, the circular buffer with modular wrap-around, telling full from empty, growing a ring without breaking order, double-ended deques, and the two-stack queue whose amortized O(1) is proved by both banker's and potential arguments."},
  {id:"Hash Tables", group:"dsa", level:3, link:"dsa/data-structures/hash-tables.html", desc:"Turning a key into an address: hash functions and what makes one good, the pigeonhole guarantee of collisions, chaining vs open addressing (linear, quadratic, double hashing), load factor and resizing, universal and perfect hashing, and why the expected O(1) is expected and not worst-case."},
  {id:"Hash Functions & Compression", group:"dsa", level:4, link:"dsa/data-structures/hash-tables/hash-functions.html", desc:"From the map ADT to an array index: direct addressing and why it fails for large key universes, the split into hash code then compression, what makes a hash function good and the uniformity hypotheses every bound assumes, and the division (prime m) and multiplication (golden-ratio, power-of-two m) methods."},
  {id:"Separate Chaining & Load Factor", group:"dsa", level:4, link:"dsa/data-structures/hash-tables/separate-chaining.html", desc:"Why collisions are guaranteed by the pigeonhole principle, resolving them by chaining each bucket into a list, the load factor α = n/m as the single parameter of cost, and what chaining really costs — Θ(1 + α) expected search and a longest chain near log n / log log n."},
  {id:"Open Addressing & Probing", group:"dsa", level:4, link:"dsa/data-structures/hash-tables/open-addressing.html", desc:"Storing every entry in the array itself and probing for a free slot: linear, quadratic and double hashing, primary and secondary clustering compared, the probe theorems giving 1/(1 − α) and (1/α)·ln(1/(1 − α)) expected probes, and why deletion needs tombstones."},
  {id:"Rehashing, Universal & Perfect Hashing", group:"dsa", level:4, link:"dsa/data-structures/hash-tables/rehashing-universal-perfect.html", desc:"Keeping α bounded by growing the table and rehashing with amortized O(1) insert, spreading that rehash incrementally across two tables to avoid latency spikes, universal hashing to make the expected bound hold against adversarial keys, and two-level perfect hashing for worst-case O(1) lookup on a static set."},
  {id:"Modern Hash Tables & Bloom Filters", group:"dsa", level:4, link:"dsa/data-structures/hash-tables/modern-hashing-bloom.html", desc:"Schemes that move entries on insertion — Robin Hood, cuckoo and hopscotch — how library implementations depart from the textbook, what hashing cannot do (order, range, predecessor and prefix queries), Bloom filters trading false positives for bits, and hashing beyond the table from consistent hashing to MinHash and LSH."},
  {id:"Heaps & Priority Queues", group:"dsa", level:3, link:"dsa/data-structures/heaps-priority-queues.html", desc:"A partial order that is cheap to maintain: the binary heap as an implicit array tree, sift-up/sift-down, why bottom-up heapify is O(n) and not O(n log n), heapsort, d-ary and Fibonacci heaps, and the priority-queue interface that Dijkstra, Huffman and top-k streaming all call."},
  {id:"Binary Heap Array & Sift Operations", group:"dsa", level:4, link:"dsa/data-structures/heaps-priority-queues/binary-heap-operations.html", desc:"The binary heap as an implicit complete tree in an array: parent and child index arithmetic in 0- and 1-based form, the exact height ⌊log₂ n⌋, the priority queue ADT and its three naive implementations, sift-up and sift-down with their comparison bounds, and the single-violation principle behind both invariants."},
  {id:"Build-Heap & Heapsort", group:"dsa", level:4, link:"dsa/data-structures/heaps-priority-queues/build-heap-heapsort.html", desc:"Building a heap bottom-up in Θ(n) with the sum-over-heights proof and why repeated insertion is Θ(n log n) in the worst case, then heapsort in place with its worst, best and average analysis, the bottom-up variant's one comparison per level, and why it usually loses to mergesort and quicksort."},
  {id:"Heap Handles, d-ary & Mergeable Heaps", group:"dsa", level:4, link:"dsa/data-structures/heaps-priority-queues/handles-dary-mergeable.html", desc:"Extending the priority queue beyond insert and extract: handles that support decreaseKey and delete on an array heap through an inverse position map, d-ary heaps trading shorter trees for wider nodes and cheaper inserts, and mergeable heaps with the binomial heap as the bridge to Fibonacci heaps."},
  {id:"Fibonacci Heaps & van Emde Boas Trees", group:"dsa", level:4, link:"dsa/data-structures/heaps-priority-queues/fibonacci-van-emde-boas.html", desc:"Fibonacci heaps as lazy root lists analysed with a potential Φ: extractMin paying deferred work by consolidation in O(log n) amortized, decreaseKey in O(1) amortized by cutting and cascading, the degree bound behind the name, and van Emde Boas trees giving O(log log u) operations on integer keys by square-root recursion."},
  {id:"Heap Applications: Graphs, Top-k & Merging", group:"dsa", level:4, link:"dsa/data-structures/heaps-priority-queues/heap-applications.html", desc:"Where heaps earn their keep: what the heap buys Dijkstra and Prim and why the theoretical winner rarely wins, what standard libraries provide and omit, top-k selection over streams, the running median with two heaps, merging k sorted lists in O(n log k) for external sorting, and what an array heap's memory locality really is."},
  {id:"Trees & Binary Search Trees", group:"dsa", level:3, link:"dsa/data-structures/trees-bst.html", desc:"Hierarchy as a data structure: rooted trees, height and depth, the four traversals, binary trees and their array/linked layouts, the binary-search-tree invariant, search/insert/delete, and why an unbalanced BST degenerates to a linked list."},
  {id:"Binary Tree Shapes & Representations", group:"dsa", level:4, link:"dsa/data-structures/trees-bst/binary-tree-shapes.html", desc:"The vocabulary and storage of binary trees: full, complete, perfect and degenerate shapes, the height bounds ⌊log₂ n⌋ ≤ h ≤ n − 1, linked, parent-pointer and first-child/next-sibling representations, the implicit array layout and its waste on sparse trees, and computing depth and height recursively."},
  {id:"Binary Tree Traversals", group:"dsa", level:4, link:"dsa/data-structures/trees-bst/tree-traversals.html", desc:"The four traversals — preorder, inorder, postorder and level-order — recursively in Θ(n) time with O(h) stack depth, iteratively with an explicit stack, in O(1) extra space by Morris threading, unified by the Euler tour, applied to expression trees for prefix, infix and postfix, and seen in file systems, the DOM and parse trees."},
  {id:"BST Search, Insert & Delete", group:"dsa", level:4, link:"dsa/data-structures/trees-bst/bst-operations.html", desc:"The binary-search-tree invariant and every operation that relies on it in O(h): search, minimum and maximum, successor and predecessor, range queries and in-order iteration, insertion as a leaf, lowest common ancestor and building a balanced tree from sorted input, and deletion's three cases via transplant."},
  {id:"BST Height, Random BSTs & Catalan Counting", group:"dsa", level:4, link:"dsa/data-structures/trees-bst/bst-height-analysis.html", desc:"Why the shape decides everything: inorder traversal is sorted and tree sort makes quicksort's comparisons, every operation is O(h) so a chain costs Θ(n), randomly built BSTs with expected depth about 1.39 log₂ n, successor-only deletion drifting toward a conjectured Θ(√n) mean depth, the Catalan count of shapes, and augmenting with rank, select and intervals."},
  {id:"Balanced & Multiway Trees", group:"dsa", level:3, link:"dsa/data-structures/balanced-trees.html", desc:"Keeping the height logarithmic: rotations, AVL trees and their balance factor, red-black trees and the invariants that bound height at 2·log(n+1), B-trees and why disk and cache block sizes dictate the fan-out, plus tries, skip lists and Fenwick/segment trees."},
  {id:"AVL Trees & Rotations", group:"dsa", level:4, link:"dsa/data-structures/balanced-trees/avl-rotations.html", desc:"The rotation as the one primitive that changes shape without breaking search order, the AVL height-balance invariant and its Fibonacci-derived 1.44 log n height bound, insertion's four cases fixed by one single or double rotation, deletion's rebalancing cascade, and AVL heights and rotation counts measured."},
  {id:"Red-Black Trees", group:"dsa", level:4, link:"dsa/data-structures/balanced-trees/red-black.html", desc:"The five red-black properties and the black-height lemma that caps height at 2·log₂(n + 1), insertion's three cases with at most two rotations, deletion's four cases with at most three, the red-black tree as a 2-3-4 tree in disguise, and AVL versus red-black measured head to head."},
  {id:"B-Trees & B⁺-Trees", group:"dsa", level:4, link:"dsa/data-structures/balanced-trees/b-trees.html", desc:"Multiway search trees: 2-3 and 2-3-4 trees with split and fuse, B-trees defined by minimum degree t with their log_t n height bound, search, split-on-insert and delete, the I/O model where fan-out follows the disk block, B⁺-trees with chained leaves for range scans and indexes, and B-trees in memory with cache lines as blocks."},
  {id:"Splay Trees & Skip Lists", group:"dsa", level:4, link:"dsa/data-structures/balanced-trees/splay-skip-lists.html", desc:"Balance without a stored invariant: splay trees that move every accessed key to the root by zig, zig-zig and zig-zag steps, analysed with the potential Φ = Σ log size and the access lemma to amortized O(log n), and skip lists whose coin-flip levels give expected O(log n) search, linear space and easy concurrency."},
  {id:"Tries, Segment Trees & Fenwick Trees", group:"dsa", level:4, link:"dsa/data-structures/balanced-trees/tries-segment-fenwick.html", desc:"Trees indexed by structure rather than comparison: tries that search in O(L) by key digit and their space problem, radix/Patricia and ternary search tries as the fix, segment trees for O(log n) range queries, lazy propagation for range updates, and the Fenwick tree's lowbit trick for prefix sums."},
  {id:"Augmented Trees, Interval Trees & Treaps", group:"dsa", level:4, link:"dsa/data-structures/balanced-trees/augmented-interval-treaps.html", desc:"Storing extra per-node fields that survive rotations: subtree sizes for order-statistic select and rank, the augmentation method in general, interval trees answering overlap queries in O(log n) via a max-endpoint field, and treaps — random priorities in heap order — with expected O(log n) split, join and implicit sequences."},
  {id:"Graph Representations & Traversal", group:"dsa", level:3, link:"dsa/data-structures/graphs.html", desc:"Relationships as first-class data: adjacency lists vs matrices and the density at which each wins, directed/undirected/weighted variants, breadth-first and depth-first search, the edge classification DFS induces, cycle detection, topological order, connected and strongly connected components."},

  {id:"Graph Storage: Matrix, Lists & CSR", group:"dsa", level:4, link:"dsa/data-structures/graphs/graph-storage.html", desc:"The graph ADT and which representation makes each operation cheap: the V² adjacency matrix with O(1) edge queries and its algebra, adjacency lists and the maps and sets that fix their weak query, the edge list, compressed sparse row, measured costs and the density at which a matrix wins, and implicit graphs never stored."},
  {id:"Breadth-First Search & Bipartiteness", group:"dsa", level:4, link:"dsa/data-structures/graphs/breadth-first-search.html", desc:"What a traversal is — a visited set, a frontier and a discipline — then breadth-first search with its queue and layers, the proof that it computes shortest paths in edges in Θ(V + E), path reconstruction, multi-source distances and shortest-path counting, and bipartiteness by 2-colouring with the odd cycle it returns on failure."},
  {id:"Depth-First Search & Edge Classification", group:"dsa", level:4, link:"dsa/data-structures/graphs/depth-first-search.html", desc:"Depth-first search in recursive and explicit-stack form with discovery and finishing times, the parenthesis and white-path theorems those timestamps guarantee, the four edge classes of a directed graph and two of an undirected one, cycle detection as the absence of back edges, and connected components cross-checked against union-find."},
  {id:"Topological Sort, SCCs & Articulation Points", group:"dsa", level:4, link:"dsa/data-structures/graphs/topological-sort-scc.html", desc:"What DFS timestamps extract from structure: topological sort as reverse finishing order with its proof beside Kahn's in-degree algorithm, how many orders a DAG has, strongly connected components by the two-pass reverse-graph method and the condensation DAG, the single-pass low-link algorithm, and articulation points and bridges."},
  {id:"Traversal Trade-offs & Weighted Graphs", group:"dsa", level:4, link:"dsa/data-structures/graphs/traversal-tradeoffs.html", desc:"BFS against DFS on memory, visit order and what each finds, why recursive DFS overflows on a long path and the explicit stack that does not, union-find as the dynamic-connectivity structure, what changes once edges carry weights, and where graphs reappear in machine learning from message passing to proximity graphs."},
  // Algorithm Design & Analysis — parts 1-7
  {id:"Algorithm Analysis", group:"dsa", level:3, link:"dsa/algorithms/analysis.html", desc:"The language of cost: the RAM model, O/Ω/Θ/o/ω with their formal definitions, the growth hierarchy, best/average/worst case, solving recurrences by substitution, recursion tree and the Master theorem, amortized analysis (aggregate, accounting, potential), and space complexity."},
  {id:"Cost Models & Step Counting", group:"dsa", level:4, link:"dsa/algorithms/analysis/cost-models-counting.html", desc:"What an algorithm's cost is measured in and why stopwatch timing cannot replace it: the RAM model and its unit-cost assumptions, counting steps exactly, best, worst and average cases distinguished, and an average-case analysis carried all the way through for insertion sort over random permutations."},
  {id:"Asymptotic Notation & Growth Rates", group:"dsa", level:4, link:"dsa/algorithms/analysis/asymptotic-notation.html", desc:"Compressing an exact count into a growth rate: O, Ω and Θ defined formally with witnesses, strict o and ω, the rules for manipulating bounds, the growth hierarchy from constant to factorial, where constants decide the crossover, and the standard patterns for reading the cost of loops."},
  {id:"Recurrences & the Master Theorem", group:"dsa", level:4, link:"dsa/algorithms/analysis/recurrences-master-theorem.html", desc:"Solving the recurrences that recursive algorithms produce: setting T(n) up from the code, proving a guess by substitution, reading the sum off a recursion tree, the Master theorem's three cases for T(n) = a·T(n/b) + f(n), and the gaps, regularity condition and shapes it cannot handle."},
  {id:"Amortized Analysis", group:"dsa", level:4, link:"dsa/algorithms/analysis/amortized-analysis.html", desc:"Bounding the cost of a whole sequence of operations rather than the worst single one: the aggregate, accounting and potential methods side by side, and the dynamic array worked through all three — why doubling gives O(1) amortized append and why a growth factor too close to 1 or shrinking too eagerly breaks it."},
  {id:"Space Complexity & Empirical Analysis", group:"dsa", level:4, link:"dsa/algorithms/analysis/space-empirical-limits.html", desc:"The checks around a time bound: auxiliary versus total space and the recursion stack that is easy to forget, the doubling test as disciplined empirical analysis for catching mismatches and finding constants, and the situations — hidden constants, the memory hierarchy, small inputs, the wrong cost model — where asymptotic answers mislead."},
  {id:"Recursion, Divide & Conquer", group:"dsa", level:3, link:"dsa/algorithms/divide-conquer.html", desc:"Solving a problem with smaller copies of itself: the call stack and recursion mechanics, base cases and termination, the divide-and-conquer template and its recurrence, mergesort/Karatsuba/Strassen/FFT as instances, and backtracking with pruning as recursion over a search tree."},
  {id:"Recursion & the Call Stack", group:"dsa", level:4, link:"dsa/algorithms/divide-conquer/recursion-call-stack.html", desc:"Recursion as a mechanism: why a recursion terminates by a decreasing measure, how strong induction proves it correct, the call tree that its cost is read from, and recursion depth as stack space — with the limits and overflow behaviour that bound how deep a real program can go."},
  {id:"Recursion Shapes, Tail Calls & Explicit Stacks", group:"dsa", level:4, link:"dsa/algorithms/divide-conquer/recursion-shapes-iteration.html", desc:"The shapes a recursion takes — linear, binary, multiple — and what each costs, when a loop is the better expression, tail recursion and why some languages do not eliminate it, converting any recursion to an explicit stack, and spotting the overlapping subproblems that hand the problem to memoization."},
  {id:"Divide & Conquer Template & Recurrences", group:"dsa", level:4, link:"dsa/algorithms/divide-conquer/dc-template-classics.html", desc:"The divide-and-conquer template and the recurrence T(n) = a·T(n/b) + f(n) it produces, worked through mergesort, binary search as the a = 1 case and the maximum-subarray split — then Kadane's linear scan as the reminder that a split is not always the best structure."},
  {id:"Karatsuba, Strassen, FFT & Closest Pair", group:"dsa", level:4, link:"dsa/algorithms/divide-conquer/fast-arithmetic-geometry.html", desc:"Divide and conquer that beats the obvious bound by cutting the number or cost of subproblems: Karatsuba's three multiplications for n^1.585, Strassen's seven for n^2.807, closest pair of points in Θ(n log n) via the strip argument, the FFT sketched, and the constant factors and crossovers where splitting stops paying."},
  {id:"Backtracking, Branch & Bound and Minimax", group:"dsa", level:4, link:"dsa/algorithms/divide-conquer/backtracking-game-trees.html", desc:"Recursion as exhaustive search made affordable by pruning: the backtracking template, n-queens with constraint checks, enumerating subsets and permutations, branch and bound against an optimistic bound, and game trees searched by minimax with alpha-beta cutting the explored nodes toward the square root."},
  {id:"Randomized Quicksort & Linear-Time Selection", group:"dsa", level:4, link:"dsa/algorithms/divide-conquer/randomized-selection.html", desc:"Divide and conquer when the split depends on the data: a random pivot makes quicksort's expected cost Θ(n log n) on every input, and partition-based selection discards one side each round — expected linear with random pivots, worst-case linear with median of medians."},
  {id:"Sorting & Searching", group:"dsa", level:3, link:"dsa/algorithms/sorting-searching.html", desc:"Imposing order and exploiting it: insertion/selection/bubble, mergesort, quicksort and its partition schemes and pivot choice, heapsort, the Ω(n log n) comparison lower bound and how counting/radix/bucket sort escape it, stability, binary search and its off-by-one variants, and selection in linear time."},
  {id:"Elementary Sorts & Shellsort", group:"dsa", level:4, link:"dsa/algorithms/sorting-searching/elementary-sorts.html", desc:"The quadratic sorts and why they still matter: insertion sort's sorted-prefix invariant and its cost measured in inversions, selection and bubble sort, shellsort's gap sequences breaking the quadratic barrier, cycle sort for the fewest writes, and odd-even transposition as the parallel-friendly neighbour-swap sort."},
  {id:"Comparison Lower Bound & Mergesort", group:"dsa", level:4, link:"dsa/algorithms/sorting-searching/lower-bound-mergesort.html", desc:"Why no comparison sort beats Ω(n log n) — the decision-tree argument over n! leaves — and the sort that meets it unconditionally: merging with its invariant and stability, mergesort's exact comparison counts, and the bottom-up, natural and linked-list variants."},
  {id:"Quicksort & Partitioning", group:"dsa", level:4, link:"dsa/algorithms/sorting-searching/quicksort-partitioning.html", desc:"Quicksort taken apart: the partition invariant, Lomuto and Hoare partitions and their different contracts, pivot choice, three-way partitioning for equal keys, the expected 2n·ln n comparison analysis against the quadratic worst case, and the cutoff and introsort fallback that make it practical."},
  {id:"Heapsort, Non-Comparison & Library Sorts", group:"dsa", level:4, link:"dsa/algorithms/sorting-searching/heapsort-linear-library.html", desc:"Heapsort's in-place guarantee and the three n log n sorts compared, then escaping the comparison floor by using key structure — counting sort, LSD and MSD radix sort, bucket sort under a uniformity assumption — plus sorting records by key and indirection, and the hybrid designs real standard libraries ship."},
  {id:"Binary Search & External Sorting", group:"dsa", level:4, link:"dsa/algorithms/sorting-searching/binary-search-external.html", desc:"What sorted order buys: when linear search still wins, binary search with its invariant and the two classic bugs, lower- and upper-bound variants, searching on a monotone predicate, galloping and interpolation search, the trade-offs of trees, hashes and skip lists, and external sorting with the k-way merge when data exceeds memory."},
  {id:"Greedy Algorithms", group:"dsa", level:3, link:"dsa/algorithms/greedy.html", desc:"Take the locally best option and never reconsider: when that is provably optimal (greedy-choice property, optimal substructure, matroids), the exchange argument that proves it, activity selection, Huffman coding, fractional knapsack and scheduling — and the problems where greedy is confidently wrong."},
  {id:"Greedy Proof Templates & Activity Selection", group:"dsa", level:4, link:"dsa/algorithms/greedy/proofs-activity-selection.html", desc:"The greedy-choice and optimal-substructure properties and how greedy differs from dynamic programming, the three proof templates — greedy stays ahead, exchange and matroid — and activity selection worked through its DP view, the earliest-finish rule and its proof, three plausible rules refuted by counterexample, ties and cost."},
  {id:"Exchange Arguments: Scheduling, Coins & Knapsack", group:"dsa", level:4, link:"dsa/algorithms/greedy/scheduling-coins-knapsack.html", desc:"The exchange argument at work and at its limits: interval partitioning with the depth lower bound, minimising maximum lateness by removing inversions, coin change where largest-coin-first is optimal for some coin systems and not others, fractional knapsack by value density, and 0/1 knapsack where the rule fails and DP takes over."},
  {id:"Huffman Coding & Prefix Codes", group:"dsa", level:4, link:"dsa/algorithms/greedy/huffman-coding.html", desc:"Prefix codes as binary tries and the cost of a code tree, Huffman's algorithm merging the two lightest subtrees with a priority queue, its optimality through the greedy-choice and substructure lemmas, the entropy bound H ≤ L < H + 1 with ties and non-uniqueness, and canonical codes as real compressors use them."},
  {id:"Matroids & Greedy on Graphs", group:"dsa", level:4, link:"dsa/algorithms/greedy/matroids-graph-greedy.html", desc:"Matroids and their exchange axiom with examples that are and are not matroids, the theorem that greedy is optimal on every weighted matroid and its converse, unit-time task scheduling as a matroid in disguise, the cut property that makes Kruskal, Prim and Dijkstra greedy, and stays-ahead proofs for fuel stops and jumps along a line."},
  {id:"Greedy Approximation & Heuristics", group:"dsa", level:4, link:"dsa/algorithms/greedy/approximation-heuristics.html", desc:"Greedy where exactness is out of reach: set cover within H(n) ≈ ln n of optimal and why that is essentially best possible, list scheduling as a (2 − 1/m)-approximation, Horn-formula satisfiability solved exactly, greedy in machine learning from decision trees to beam search, and nearest-neighbour tours showing how bad locally best can be."},
  {id:"Dynamic Programming", group:"dsa", level:3, link:"dsa/algorithms/dynamic-programming.html", desc:"Reuse instead of recompute: optimal substructure plus overlapping subproblems, memoization vs tabulation, designing the state and the transition, the classic recurrences (LCS, edit distance, knapsack, matrix chain, LIS, coin change), DP over DAGs and trees, and reconstructing the solution from the table."},
  {id:"DP Foundations & Memoization", group:"dsa", level:4, link:"dsa/algorithms/dynamic-programming/foundations-memoization.html", desc:"The method behind every dynamic program: optimal substructure and where it fails, overlapping subproblems turning a recursion tree into a graph, rod cutting taken from 2ⁿ to Θ(n²), evaluation order as a topological sort, memoization versus tabulation measured, and a checklist for designing the state."},
  {id:"Knapsack & Counting DP", group:"dsa", level:4, link:"dsa/algorithms/dynamic-programming/knapsack-counting.html", desc:"The one- and two-index workhorses: Fibonacci, stairs, house robber and Kadane as 1-D recurrences, Pascal's triangle, coin change counted three ways, the 0/1 knapsack (item, capacity) table with its rolling-array, unbounded and bounded variants and pseudo-polynomial cost, and weighted interval scheduling via p(j)."},
  {id:"Sequence DP: LCS, Edit Distance & LIS", group:"dsa", level:4, link:"dsa/algorithms/dynamic-programming/sequence-dp.html", desc:"Dynamic programs over pairs of sequences: longest common subsequence, edit distance as a shortest path in an alignment DAG, Hirschberg recovering the alignment in linear space, dynamic time warping for time series, and longest increasing subsequence in Θ(n²) and Θ(n log n)."},
  {id:"Interval & Tree DP", group:"dsa", level:4, link:"dsa/algorithms/dynamic-programming/interval-tree-dp.html", desc:"States indexed by a contiguous range or a subtree: matrix-chain ordering and the Catalan count it avoids, optimal binary search trees by expected cost, interval DP for palindromes and burst-balloons with the last-split trick, and DP on trees combining child results in one post-order pass."},
  {id:"DAG, Bitmask & Digit DP", group:"dsa", level:4, link:"dsa/algorithms/dynamic-programming/dag-bitmask-digit-dp.html", desc:"Dynamic programming over less obvious state spaces: any DAG in topological order and the shortest-path algorithms that fall out of it, subsets encoded as bitmasks with Held–Karp's O(2ⁿn²) travelling-salesman DP, and digit DP for counting numbers below a bound with a tight flag."},
  {id:"DP Optimisations, Bellman & Viterbi", group:"dsa", level:4, link:"dsa/algorithms/dynamic-programming/optimisations-bellman-viterbi.html", desc:"Making tables smaller and faster and following the recurrence into learning: rolling arrays and how to reconstruct after rolling, the named speedups with the exact hypotheses each needs, and the Bellman equation, Viterbi decoding and CTC as dynamic programs — contrasted with beam search, which is not one."},
  {id:"Shortest Paths, MST & Flow", group:"dsa", level:3, link:"dsa/algorithms/shortest-paths-mst-flow.html", desc:"The weighted-graph algorithms: relaxation and the shortest-path optimality condition, Dijkstra, Bellman-Ford and negative cycles, DAG relaxation, Floyd-Warshall and A*; Kruskal and Prim with union-find; and max-flow/min-cut with Ford-Fulkerson and Edmonds-Karp."},
  {id:"Relaxation & Dijkstra", group:"dsa", level:4, link:"dsa/algorithms/shortest-paths-mst-flow/relaxation-dijkstra.html", desc:"The single-source shortest-path core: relaxation and the optimality conditions every algorithm maintains, why negative edges and cycles break things, and Dijkstra stepped, proved correct for non-negative weights, and costed with array, binary-heap, Fibonacci-heap and lazy-deletion queues."},
  {id:"Bellman-Ford, DAGs & Constraints", group:"dsa", level:4, link:"dsa/algorithms/shortest-paths-mst-flow/bellman-ford-dags.html", desc:"Shortest paths when Dijkstra's assumptions fail or are overkill: Bellman-Ford's rounds and negative-cycle detection proved by path relaxation and the DP view, one-pass DAG relaxation and critical paths, difference constraints as a shortest-path system, and 0-1 BFS and Dial's buckets for small integer weights."},
  {id:"All-Pairs Shortest Paths & A*", group:"dsa", level:4, link:"dsa/algorithms/shortest-paths-mst-flow/all-pairs-a-star.html", desc:"Distances between every pair of vertices — repeated Dijkstra, min-plus matrix squaring, the Floyd-Warshall DP stepped, and Johnson's potential reweighting for sparse graphs with negative edges — and the opposite case, A* steering toward one goal with admissible and consistent heuristics."},
  {id:"Minimum Spanning Trees & Union-Find", group:"dsa", level:4, link:"dsa/algorithms/shortest-paths-mst-flow/minimum-spanning-trees.html", desc:"The cheapest tree connecting every vertex: the cut and cycle properties that make greedy correct, Kruskal stepped with union-find built from rank and path compression to α(n), Prim as Dijkstra with a different key, and Borůvka, second-best MSTs, MST versus shortest-path trees and MST clustering."},
  {id:"Max-Flow Algorithms", group:"dsa", level:4, link:"dsa/algorithms/shortest-paths-mst-flow/max-flow.html", desc:"Maximum flow from first principles: flow networks, residual graphs, augmenting paths and cuts, Ford-Fulkerson with the max-flow min-cut theorem, Edmonds-Karp's O(VE²) bound proved and measured, and push-relabel's preflows and heights reaching O(V²E)."},
  {id:"Matching & Flow Applications", group:"dsa", level:4, link:"dsa/algorithms/shortest-paths-mst-flow/matching-flow-applications.html", desc:"What max-flow buys once it exists: bipartite matching as a unit-capacity flow with König's and Hall's theorems, edge-disjoint paths, project selection, image segmentation by min-cut and circulations with demands, and where weighted-graph algorithms reappear across machine learning."},
  {id:"NP-Completeness & Approximation", group:"dsa", level:3, link:"dsa/algorithms/np-completeness.html", desc:"Where efficient algorithms stop: P, NP, NP-hard and NP-complete, polynomial-time reductions and what Cook-Levin established, the classic complete problems, and what to do next — approximation algorithms with proven ratios, randomization, parameterised tractability, and heuristics with no guarantee at all."},
  {id:"Problems, P & NP", group:"dsa", level:4, link:"dsa/algorithms/np-completeness/problems-p-np.html", desc:"What a problem formally is and what efficient means: encodings and input size, decision vs search vs optimisation, the class P and why it is robust, and NP defined by checkable certificates — with the verifier run on real instances."},
  {id:"Reductions & Cook–Levin", group:"dsa", level:4, link:"dsa/algorithms/np-completeness/reductions-cook-levin.html", desc:"Polynomial-time reductions as the tool that transfers hardness, the definitions of NP-hard and NP-complete and what P = NP would mean, the Cook–Levin theorem via Circuit-SAT, and the SAT → CNF-SAT → 3-SAT chain that seeds every later reduction."},
  {id:"The Classic Reductions", group:"dsa", level:4, link:"dsa/algorithms/np-completeness/classic-reductions.html", desc:"The reduction map from 3-SAT outward, worked gadget by gadget with every small instance brute-forced: Clique, Vertex Cover and Independent Set, Hamiltonian cycle and TSP, subset sum / partition / knapsack, and graph colouring."},
  {id:"co-NP & Beyond NP", group:"dsa", level:4, link:"dsa/algorithms/np-completeness/boundary-conp-beyond.html", desc:"Where the easy–hard boundary actually runs between near-identical problem pairs, co-NP and the problems of unknown status, the classes beyond NP up to undecidability, and the NP-hardness results that shape machine-learning practice."},
  {id:"Approximation Algorithms", group:"dsa", level:4, link:"dsa/algorithms/np-completeness/approximation.html", desc:"Giving up exactness but keeping a proof: approximation ratios and the APX/PTAS/FPTAS hierarchy, vertex cover at 2, metric TSP at 2 then 3/2, greedy set cover's ln n bound, MAX-3-SAT at 7/8 derandomised, and the knapsack FPTAS by value rounding."},
  {id:"Exact Search, FPT & Heuristics", group:"dsa", level:4, link:"dsa/algorithms/np-completeness/exact-heuristics-solvers.html", desc:"The other three responses to a hardness proof: exact exponential search with branch and bound and DP over subsets, parameterised algorithms with kernels and bounded search trees, local search and population heuristics without guarantees, and the CDCL SAT and ILP solvers that make NP-hard problems routine — with the phase transition measured."},
  // Algorithm Design & Analysis — parts 8-10 (selected topics)
  {id:"Computational Geometry", group:"dsa", level:3, link:"dsa/algorithms/geometry.html", desc:"Algorithms on points, segments and polygons: the orientation test and why cross products replace angles and slopes, segment intersection, the sweep-line method, convex hulls (Graham scan, Jarvis march, monotone chain) and their Ω(n log n) bound, divide-and-conquer closest pair, point-in-polygon, and range searching with kd-trees and range trees."},
  {id:"Geometric Primitives & Robust Predicates", group:"dsa", level:4, link:"dsa/algorithms/geometry/robust-primitives.html", desc:"Why floating-point geometry breaks and the two principled fixes, points and vectors with the cross product, the orientation test that replaces angles and slopes, how many bits exact integer predicates need and how filtered predicates stay fast, and Bresenham's line rasterised entirely in integers."},
  {id:"Segment Intersection & Sweep Lines", group:"dsa", level:4, link:"dsa/algorithms/geometry/segment-intersection-sweep.html", desc:"Deciding whether two segments meet with two straddle tests and the collinear case, the sweep-line paradigm of event queue, ordered status structure and invariant, detecting any intersection in O(n log n) by checking only neighbours, and Bentley–Ottmann reporting all k crossings in O((n + k) log n) with its degeneracies."},
  {id:"Convex Hull Algorithms", group:"dsa", level:4, link:"dsa/algorithms/geometry/convex-hulls.html", desc:"The convex hull as output and building block, Graham scan with the polar-sort stack invariant, Andrew's monotone chain doing the same without angles, output-sensitive Jarvis march in O(nh), quickhull, the Ω(n log n) lower bound by reduction from sorting, and the collinear and duplicate points that break naive code."},
  {id:"Closest Pair, Polygons & Range Search", group:"dsa", level:4, link:"dsa/algorithms/geometry/polygons-range-search.html", desc:"Closest pair through the packing argument and an expected-linear random grid, polygon area, orientation and convexity by the shoelace formula, point-in-polygon by ray casting versus winding number with half-open rules for degenerate cases, and orthogonal range search with kd-trees, range trees with fractional cascading, and plain grids."},
  {id:"Parallel Algorithms", group:"dsa", level:3, link:"dsa/algorithms/parallel.html", desc:"Pricing an algorithm on many processors: the fork-join model, work and span, parallelism and Brent's bound, Amdahl's and Gustafson's laws, race conditions and determinacy, parallel loops, prefix sums (scan), parallel merge sort and matrix multiplication, and why span, not work, decides the speedup."},
  {id:"PRAM Model & Work-Span", group:"dsa", level:4, link:"dsa/algorithms/parallel/pram-work-span.html", desc:"The PRAM model and why it is only a starting point, fork-join programs with spawn, sync and parallel for, the computation DAG they unfold into, work T₁ and span T∞ with parallelism as their ratio, and the work and span laws that cap the speedup any scheduler can achieve."},
  {id:"Parallel Scheduling & Scaling Laws", group:"dsa", level:4, link:"dsa/algorithms/parallel/scheduling-scaling.html", desc:"Greedy scheduling and Brent's bound T_p ≤ T₁/p + T∞ that makes work and span sufficient, the randomised work-stealing scheduler real runtimes use, Amdahl's law for a fixed problem against Gustafson's law for a growing one, and strong versus weak scaling as the experiments that test each."},
  {id:"Span Recurrences, Races & Synchronisation", group:"dsa", level:4, link:"dsa/algorithms/parallel/span-races-synchronisation.html", desc:"Reading two recurrences off parallel code, where spawned calls contribute the maximum rather than the sum of their spans, the span of parallel loops, determinacy races and why they make results nondeterministic, and what coordination costs through atomics, locks, reducers and false sharing on cache lines."},
  {id:"Parallel Prefix Sums & Scan", group:"dsa", level:4, link:"dsa/algorithms/parallel/parallel-scan.html", desc:"Prefix sums as the primitive behind parallel data movement, the naive doubling scan with Θ(log n) span but Θ(n log n) work, the work-efficient up-sweep and down-sweep scan that keeps Θ(n) work, and what scan unlocks: stream compaction, partition, radix sort and segmented scan."},
  {id:"Parallel Merge Sort, Matrix Multiply & BFS", group:"dsa", level:4, link:"dsa/algorithms/parallel/sort-matrix-mapreduce-bfs.html", desc:"Merge sort whose serial merge caps span at Θ(n) and the binary-search-splitting merge that brings it to Θ(log³ n), matrix multiplication by loops, divide and conquer and Strassen, systolic arrays as algorithms built into hardware, map, reduce and MapReduce, and breadth-first search parallelised level by level."},
  {id:"Online & Randomized Algorithms", group:"dsa", level:3, link:"dsa/algorithms/online-randomized.html", desc:"Deciding without seeing the future, and using coin flips on purpose: competitive analysis, ski rental, paging (LRU, FIFO, Belady's offline optimum, the marker algorithm), list update and move-to-front, the hiring and secretary problems, probabilistic analysis with indicator random variables, Las Vegas vs Monte Carlo, and generating randomness itself (LCGs, Fisher-Yates)."},
  {id:"Competitive Analysis & Ski Rental", group:"dsa", level:4, link:"dsa/algorithms/online-randomized/competitive-analysis.html", desc:"Online problems measured by the competitive ratio against an offline optimum, deterministic versus randomized algorithms and the three adversary models, ski rental's break-even rule with the proof that 2 − 1/B is the best deterministic ratio, and the randomized rule reaching e/(e − 1) ≈ 1.582 against an oblivious adversary."},
  {id:"Online Paging & List Update", group:"dsa", level:4, link:"dsa/algorithms/online-randomized/paging-list-update.html", desc:"Paging as the canonical online problem: Belady's furthest-in-future rule as the offline optimum, LRU and FIFO as k-competitive with no deterministic policy better, Belady's anomaly under FIFO, the randomized marker algorithm at 2H_k, move-to-front list update as 2-competitive by a potential function, and online load balancing and matching."},
  {id:"Probabilistic Analysis: Hiring & Secretary", group:"dsa", level:4, link:"dsa/algorithms/online-randomized/hiring-secretary.html", desc:"Probabilistic analysis over a random input order versus randomized algorithms that impose one, indicator random variables as the workhorse for expectations, the hiring problem whose expected number of hires is Hₙ ≈ ln n, and the secretary problem's observe-n/e-then-commit rule succeeding with probability tending to 1/e."},
  {id:"Las Vegas, Monte Carlo & Tail Bounds", group:"dsa", level:4, link:"dsa/algorithms/online-randomized/las-vegas-monte-carlo.html", desc:"Las Vegas algorithms with random running time against Monte Carlo algorithms with random correctness and amplification by repetition, randomized quicksort, quickselect and Karger's min cut, fingerprints and Miller–Rabin primality, the Markov, Chebyshev and Chernoff tail bounds, and balls into bins from the birthday bound to maximum load."},
  {id:"Pseudo-Randomness, Shuffling & Reservoir Sampling", group:"dsa", level:4, link:"dsa/algorithms/online-randomized/randomness-shuffling-sampling.html", desc:"Where the coins come from and how to spend them correctly: pseudo-random generators, linear congruential generators and seeding, the Fisher–Yates shuffle and the one-character bug that biases it, and reservoir sampling that keeps a uniform sample of k from a stream of unknown length."},
  {id:"Number-Theoretic Algorithms", group:"dsa", level:3, link:"dsa/algorithms/number-theory.html", desc:"Arithmetic on integers too large for a machine word: divisibility and Euclid's gcd with its extended form, modular arithmetic and inverses, fast modular exponentiation by repeated squaring, the Chinese remainder theorem, primality testing (Fermat and Miller–Rabin), RSA and why it is correct, and the cost of big-number arithmetic measured in bits."},
  {id:"GCD, Euclid & Bit Complexity", group:"dsa", level:4, link:"dsa/algorithms/number-theory/gcd-euclid.html", desc:"What big-integer addition, multiplication and division cost in bit operations, divisibility and the division theorem, the gcd as the smallest positive linear combination, Euclid's algorithm with its halving argument and Lamé's Fibonacci worst case, division-free binary gcd, and extended Euclid computing the Bézout coefficients."},
  {id:"Modular Arithmetic, Fast Exponentiation & CRT", group:"dsa", level:4, link:"dsa/algorithms/number-theory/modular-arithmetic-crt.html", desc:"The groups Zₙ and Zₙ* and Euler's φ counting the invertible residues, modular inverses and linear congruences via extended Euclid, Fermat's little theorem, Euler's theorem, orders and primitive roots, modular exponentiation by repeated squaring in O(log e) multiplications, and the Chinese remainder theorem with its uses."},
  {id:"Primality Testing, RSA & Factoring", group:"dsa", level:4, link:"dsa/algorithms/number-theory/primality-rsa-factoring.html", desc:"Primality by trial division and the Fermat test that Carmichael numbers defeat, Miller–Rabin with error at most (¼)ᵏ after k rounds, generating large primes from the prime number theorem, RSA key generation and why decryption works through Euler and the CRT, why textbook RSA is insecure, and factoring by Pollard's rho."},
  {id:"Relational & SQL", group:"dsys", level:2, desc:"Tables, keys, joins, and the SQL query language over normalized relational schemas."},
  {id:"NoSQL", group:"dsys", level:2, desc:"Non-relational stores — key-value, document, columnar, graph — for scale and flexibility."},
  {id:"Indexing", group:"dsys", level:2, desc:"Data structures (B-trees, hashes) that make lookups fast at some write/space cost."},
  {id:"Transactions (ACID)", group:"dsys", level:2, desc:"Atomicity, consistency, isolation, durability — guarantees for correct concurrent writes."},
  {id:"Sharding & Replication", group:"dsys", level:2, desc:"Partitioning data across machines and copying it for scale and availability."},
  {id:"Hadoop & MapReduce", group:"dsys", level:2, desc:"The batch paradigm that started big data: distribute work as map and reduce steps over a cluster."},
  {id:"Streaming (Kafka)", group:"dsys", level:2, desc:"Processing unbounded event streams in near-real-time; Kafka as the durable log."},
  {id:"Data Lakes", group:"dsys", level:2, desc:"Store raw data at scale in open formats, schema-on-read, for flexible downstream use."},
  {id:"Distributed Storage", group:"dsys", level:2, desc:"Spreading data across nodes (HDFS, object stores) for capacity and fault tolerance."},
  {id:"Warehouses & Lakehouses", group:"dsys", level:2, desc:"Structured analytical stores and the lakehouse blend of lake flexibility + warehouse speed."},
  {id:"Scalability", group:"dsys", level:2, desc:"Handling growth by scaling up (bigger) or out (more machines); statelessness and partitioning."},
  {id:"Load Balancing", group:"dsys", level:2, desc:"Distributing requests across servers for throughput and resilience."},
  {id:"Caching", group:"dsys", level:2, desc:"Storing hot results closer to compute to cut latency and load (CDN, Redis, app cache)."},
  {id:"Message Queues", group:"dsys", level:2, desc:"Decoupling producers and consumers with async queues (Kafka, RabbitMQ, SQS)."},
  {id:"CAP Theorem", group:"dsys", level:2, desc:"Under partition, choose consistency or availability — the core distributed-systems trade-off."},

  // Data Engineering
  {id:"ETL Pipelines", group:"deng", level:2, desc:"Extract-Transform-Load workflows that move and reshape data between systems."},
  {id:"Data Warehousing", group:"deng", level:2, desc:"Central analytical stores (Snowflake, BigQuery) optimized for queries over large history."},
  {id:"Feature Stores", group:"deng", level:2, desc:"Managed repositories of curated features, shared and consistent across training and serving."},
  {id:"Stream Processing", group:"deng", level:2, desc:"Processing data in real time as it arrives (Kafka, Flink)."},

  // Machine Learning — specific algorithms (one notes page each)
  {id:"Linear & Logistic Regression", group:"ml", level:2, link:"machine-learning/linear-logistic-regression.html", desc:"Fit a line for continuous targets, or a sigmoid-squashed line for class probabilities. Hub page: what the two share, how they differ, scaling, regularization, and when to use them; each model is a sub-topic."},
  {id:"Linear Regression", group:"ml", level:3, link:"machine-learning/linear-regression.html", desc:"Least-squares line fitting: the assumptions, why squared error (Gaussian MLE, convexity), the normal equation vs gradient descent, R²/adjusted R² and residual diagnostics, with an interactive fit."},
  {id:"Logistic Regression", group:"ml", level:3, link:"machine-learning/logistic-regression.html", desc:"Classification with a sigmoid-squashed linear score: the sigmoid derived from log-odds, cross-entropy vs MSE and convexity, decision threshold and calibration, perfect separation, softmax and one-vs-rest for many classes."},
  {id:"k-Nearest Neighbors", group:"ml", level:2, link:"machine-learning/k-nearest-neighbors.html", desc:"Classify by majority vote among the k closest stored examples — lazy and non-parametric."},
  {id:"Clustering (k-Means)", group:"ml", level:2, link:"machine-learning/clustering.html", desc:"The flagship UNSUPERVISED algorithm here (no labels): partition data by alternating assign-to-centroid and move-centroid steps."},
  {id:"Dimensionality Reduction (PCA)", group:"ml", level:2, link:"machine-learning/dimensionality-reduction-pca.html", desc:"The other major unsupervised method: project data onto the directions of greatest variance (eigenvectors of the covariance matrix) to compress while preserving structure."},
  {id:"Support Vector Machines", group:"ml", level:2, link:"machine-learning/support-vector-machines.html", desc:"Find the maximum-margin separating hyperplane; the kernel trick handles non-linear boundaries."},
  {id:"Naive Bayes", group:"ml", level:2, link:"machine-learning/naive-bayes.html", desc:"Bayes' rule with a conditional-independence assumption — fast and strong for text."},
  {id:"Decision Trees & Ensembles", group:"ml", level:2, link:"machine-learning/decision-trees.html", desc:"Recursive impurity-reducing splits, combined via bagging (forests) and boosting."},
  {id:"Regularization", group:"ml", level:2, link:"machine-learning/regularization.html", desc:"Prevent overfitting by penalizing complex models: L1 (Lasso) drives weights to zero for sparsity, while L2 (Ridge) shrinks weights uniformly. Includes deep learning dropout and label smoothing."},
  {id:"Reinforcement Learning", group:"ml", level:2, link:"machine-learning/reinforcement-learning.html", desc:"The third ML paradigm (beyond supervised/unsupervised): an agent learns a policy by trial-and-error to maximize reward from environment feedback."},
  {id:"Model Evaluation", group:"ml", level:2, link:"machine-learning/model-evaluation.html", desc:"A CROSS-CUTTING methodology (not an algorithm): how to score ANY model honestly — train/test splits, cross-validation, precision/recall, ROC-AUC."},

  // Deep Learning  (most link to the notes page)
  {id:"Feedforward / MLP", group:"dl", level:2, link:"deep-learning/neural-networks.html", desc:"The base neural network: stacked layers of weighted sums + non-linearities, trained by backprop. CNNs, Transformers, etc. are specialized variants."},
  {id:"Neurons, Nonlinearity & XOR", group:"dl", level:3, link:"deep-learning/neural-networks/neurons-xor.html", desc:"Why a hidden layer is the whole point: the neuron and the layer as one matrix product, why representation and a hierarchy of features matter, how a purely linear network collapses to one layer, XOR as the objection that stopped the field, solved by hand, and the hidden layer folding input space."},
  {id:"MLP Forward Pass & Hidden Units", group:"dl", level:3, link:"deep-learning/neural-networks/forward-hidden-units.html", desc:"The network as running tensors: the forward pass with its shapes, batching and broadcasting, parameters and arithmetic counted exactly, then the hidden-unit catalogue — the rectified family, smooth, saturating and exotic activations — and what actually makes a hidden unit good for optimisation."},
  {id:"Output Units & Likelihood Losses", group:"dl", level:3, link:"deep-learning/neural-networks/output-units-losses.html", desc:"Output units derived from maximum likelihood: a linear output with a Gaussian target giving squared error, a sigmoid with a Bernoulli target and the softplus identity, why cross-entropy pairs with saturating outputs and squared error does not, softmax and its properties, and heteroscedastic and mixture-density outputs."},
  {id:"MLP Expressivity, Depth & Inductive Bias", group:"dl", level:3, link:"deep-learning/neural-networks/expressivity-depth-bias.html", desc:"What an MLP's shape can and cannot buy: universal approximation and its limits, depth against width counted with the sawtooth as an explicit depth separation, choosing layers and width, the near-absent inductive bias, over-parameterisation, interpolation and double descent, and where MLPs live inside modern models."},
  {id:"CNNs", group:"dl", level:2, link:"deep-learning/convolutional-networks.html", desc:"Convolutional networks that slide learnable filters across grids — the backbone of vision."},
  {id:"Why Convolution: Sparsity, Sharing & Equivariance", group:"dl", level:3, link:"deep-learning/convolutional-networks/why-convolution.html", desc:"Why a dense layer fails on a grid and what convolution replaces it with: the banded, tied weight matrix, the operation and its correlation-versus-convolution naming, then the three motivations — sparse interactions, parameter sharing as an infinitely strong prior, and translation equivariance with its boundaries."},
  {id:"Conv Arithmetic & Receptive Fields", group:"dl", level:3, link:"deep-learning/convolutional-networks/arithmetic-receptive-fields.html", desc:"The arithmetic of convolution: the one output-size formula with padding, stride and dilation, the silent off-by-one traps, three-dimensional filters over volumes, one layer and then a whole network counted in parameters, FLOPs and activations, and the receptive field computed layer by layer against the effective one measured."},
  {id:"Pooling & Convolution Variants", group:"dl", level:3, link:"deep-learning/convolutional-networks/pooling-variants.html", desc:"The layer and its relatives: 1×1 convolutions as channel mixing and bottleneck, pooling and what it destroys, equivariance against invariance stated precisely, strided convolution and aliasing, grouped and depthwise-separable convolutions with their cost ratios, dilated convolution, and transposed convolution with its checkerboard."},
  {id:"Conv Blocks, Backprop & Learned Features", group:"dl", level:3, link:"deep-learning/convolutional-networks/blocks-backprop-features.html", desc:"The convolution as a trainable, computable block: conv, norm and activation and where the norm goes, backpropagation through a convolution derived and audited numerically, convolution as one matrix product via im2col and the Toeplitz view, and what a trained convolutional network actually learns layer by layer."},
  {id:"CNN Lineage, Capsules & ViTs", group:"dl", level:3, link:"deep-learning/convolutional-networks/lineage-capsules-vit.html", desc:"The architectures and their challengers: what each generation of the convnet lineage actually changed, locally connected layers that refuse to share, the critique of pooling and the viewpoint problem, capsule networks with routing by agreement and why they did not win, convnets against vision transformers, and convolution beyond images."},
  {id:"RNNs & LSTMs", group:"dl", level:2, link:"deep-learning/rnns-lstms.html", desc:"Recurrent networks that process sequences by carrying hidden state through time."},
  {id:"Recurrent Cells & Unrolling", group:"dl", level:3, link:"deep-learning/rnns-lstms/recurrent-cells.html", desc:"What recurrence buys over a feedforward net: one set of weights shared across time, the cell and its hidden state, the shapes of the unrolled forward pass, the five input–output wiring patterns and what each can express, and the loss summed over a sequence."},
  {id:"Backpropagation Through Time", group:"dl", level:3, link:"deep-learning/rnns-lstms/bptt.html", desc:"Backpropagation through time derived weight by weight: the easy output gradient, ∂L/∂W as a sum over paths, the input and bias gradients, the O(T) recursion that computes them, a worked numeric example checked by finite differences, the memory and compute cost, and truncated BPTT with its bias measured."},
  {id:"Vanishing & Exploding Gradients", group:"dl", level:3, link:"deep-learning/rnns-lstms/vanishing-exploding.html", desc:"Why the recurrent gradient dies or blows up: the repeated Jacobian, the spectral-radius threshold and why 'entries below one' is the wrong test, recurrent against feedforward depth, gradient clipping and why it cannot cure vanishing, and the non-gated remedies — initialisation, leaky units, delays and reservoirs."},
  {id:"LSTM & GRU Cells", group:"dl", level:3, link:"deep-learning/rnns-lstms/lstm-gru.html", desc:"The gated cells that fixed long-range credit assignment: the LSTM's additive cell path, each gate motivated, the constant error carousel traced, the forget-gate bias, shapes and parameter count, peephole and other variants, the GRU, and vanilla against GRU against LSTM compared."},
  {id:"Bidirectional, Stacked & Seq2seq RNNs", group:"dl", level:3, link:"deep-learning/rnns-lstms/architectures-seq2seq.html", desc:"Wiring cells into models: bidirectional RNNs and where they are illegitimate, deep stacked layers, seq2seq with its context vector, teacher forcing and exposure bias, the fixed-context bottleneck that motivated attention, sampling and beam decoding, and recursive networks over trees."},
  {id:"Attention", group:"dl", level:2, link:"deep-learning/attention.html", desc:"Learned content-based lookup: each element decides which others to read from and how much. From the 2015 seq2seq fix to MQA/GQA/MLA in modern LLMs."},
  {id:"Alignment, Scores & Scaling", group:"dl", level:3, link:"deep-learning/attention/scores-scaling.html", desc:"Where the attention score comes from: alignment derived for translation, what 'soft' lookup means, additive, bilinear and dot-product score functions compared, why the dot product is divided by √dₖ derived from its variance, and what the softmax saturates into without that scale."},
  {id:"Queries, Keys & Values", group:"dl", level:3, link:"deep-learning/attention/query-key-value.html", desc:"The three projections that turn a lookup into a layer: queries, keys and values and what each is for, shapes and parameter count, self-attention against cross-attention, attention as a weight matrix computed from the input, and the permutation equivariance that makes positional information necessary."},
  {id:"Multi-Head Attention & Masking", group:"dl", level:3, link:"deep-learning/attention/multihead-masking.html", desc:"Completing the layer: why several heads beat one, the head-dimension trade at fixed width, concatenation and the output projection, causal and padding masks, why −∞ and a large negative number are not interchangeable, and the attention backward pass audited against finite differences."},
  {id:"Attention Cost & Limits", group:"dl", level:3, link:"deep-learning/attention/cost-limits.html", desc:"What one attention layer costs and what it cannot do: the FLOP count, the sequence length at which n² actually dominates the projections, the n×n matrix as a memory bill, attention mixing tokens but never features, rank collapse with depth, and attention entropy as a diagnostic."},
  {id:"KV Cache, GQA & MLA", group:"dl", level:3, link:"deep-learning/attention/kv-cache-gqa-mla.html", desc:"Why decoding is bound by memory rather than arithmetic: the KV cache and its byte arithmetic, the arithmetic-intensity argument for why the cache binds, multi-query and grouped-query attention as ways to shrink it, and multi-head latent attention compressing keys and values into a shared latent."},
  {id:"Sparse, Linear & Flash Attention", group:"dl", level:3, link:"deep-learning/attention/efficient-attention.html", desc:"The ways around the n² wall: sliding-window and sparse patterns, linear attention through the kernel view and what it gives up, FlashAttention's IO argument with tiling and the online softmax, and what breaks in the softmax itself as context grows."},
  {id:"Transformers", group:"dl", level:2, link:"deep-learning/transformers.html", desc:"Attention-based architecture that processes whole sequences in parallel — the basis of modern LLMs."},
  {id:"Positional Encodings", group:"dl", level:3, link:"deep-learning/transformers/positional-encodings.html", desc:"Why attention needs position and the design space for supplying it: sinusoidal encodings whose offsets are linear maps, learned absolute tables, RoPE derived on rows with its frequency spectrum, ALiBi and relative buckets, NoPE via the causal mask, and which schemes extrapolate, measured."},
  {id:"Residual Stream, Norms & FFN", group:"dl", level:3, link:"deep-learning/transformers/residual-norms-ffn.html", desc:"Everything in the block around attention: the residual stream as a shared bus, pre-norm against post-norm, LayerNorm against RMSNorm, the position-wise FFN, GELU and gated units such as SwiGLU, the FFN read as key–value memory, and the block's backward pass audited."},
  {id:"Transformer Stacks & Accounting", group:"dl", level:3, link:"deep-learning/transformers/stacks-accounting.html", desc:"How blocks become a model: encoder-only and decoder-only stacks, encoder–decoder with cross-attention, the token embedding and its √d scale, unembedding, weight tying and the vocabulary cost, whole-model parameter accounting, and 6·N·D derived in MACs and FLOPs."},
  {id:"Transformer Training & Decoding", group:"dl", level:3, link:"deep-learning/transformers/training-decoding.html", desc:"The recipe that trains a transformer and the rules that read it out: teacher forcing under the causal mask, label smoothing and its loss floor, warmup then decay, AdamW with clipping and dropout, bf16 against fp16, then temperature, top-k, top-p, greedy and beam decoding run live."},
  {id:"Depth, Width & the Logit Lens", group:"dl", level:3, link:"deep-learning/transformers/shape-live-lens.html", desc:"Closing the architecture: depth against width at a fixed parameter budget, a two-layer decoder trained live in the browser with AdamW, the logit lens reading its residual stream layer by layer, and the three stacking families compared exactly at one budget."},
  {id:"Model Definitions & Loading", group:"dl", level:3, link:"deep-learning/transformers/definitions-loading.html", desc:"The transformer as code and bytes: the anatomy of a model definition, how a checkpoint is laid out, loading with dtype, meta device and placement, weight conversion at load time, heterogeneous per-layer configurations, eager/SDPA/Flash/flex attention backends, paged attention's block table, and experts backends for MoE layers."},
  {id:"KV Cache & Generation", group:"dl", level:3, link:"deep-learning/transformers/kv-cache-generation.html", desc:"Generation as an engineered loop: the KV cache as an object and its strategies costed in bytes, the generate loop and logits processors, stopping, streaming and step latency, contrastive search, DoLa and constrained beams, sliding-window perplexity, chat templates, and the levers for serving a large model."},
  {id:"Mixture of Experts", group:"dl", level:2, link:"deep-learning/mixture-of-experts.html", desc:"Sparse scaling: replace the dense FFN with many expert FFNs and route each token to only the top-k — huge parameter count, small per-token compute (Switch, Mixtral, DeepSeek)."},
  {id:"GANs", group:"dl", level:2, link:"deep-learning/generative-adversarial-networks.html", desc:"A generator and discriminator competing in a minimax game to synthesize realistic data."},
  {id:"Diffusion Models", group:"dl", level:2, link:"deep-learning/diffusion-models.html", desc:"Generate data by learning to reverse a gradual noising process — SOTA for image synthesis."},
  {id:"Autoencoders & VAEs", group:"dl", level:2, link:"deep-learning/autoencoders-vaes.html", desc:"Learning a compressed code by reconstructing the input: the undercomplete autoencoder and its relation to PCA, denoising and sparse variants, the variational autoencoder's latent distribution and the reparameterisation trick, the ELBO and its reconstruction/KL trade-off, posterior collapse, VQ-VAE's discrete codebook, and the latent space that modern diffusion models actually operate in."},
  {id:"Undercomplete Autoencoders & PCA", group:"dl", level:3, link:"deep-learning/autoencoders-vaes/undercomplete-pca.html", desc:"The bottleneck autoencoder taken precisely: the undercomplete code, the exact sense in which a linear autoencoder recovers the PCA subspace and the loose version that is wrong, nonlinear autoencoders as curved PCA, the capacity trap that defeats a bottleneck, and what depth adds."},
  {id:"Regularized Autoencoders & Manifolds", group:"dl", level:3, link:"deep-learning/autoencoders-vaes/regularized-manifolds.html", desc:"Autoencoders constrained by a penalty instead of a bottleneck: sparse codes, denoising and the reconstruction field that estimates the score, the bridge to diffusion, contractive penalties on the Jacobian, manifolds and tangent spaces, stochastic encoders and decoders, predictive sparse decomposition, and real uses."},
  {id:"VAE: ELBO & Reparameterization", group:"dl", level:3, link:"deep-learning/autoencoders-vaes/vae-elbo-reparam.html", desc:"The variational autoencoder derived: the latent-variable model and its two intractable integrals, the evidence lower bound in two decompositions with its gap, the reparameterisation trick against the score-function estimator it replaces, the full model end to end, and the scale trap in the decoder likelihood."},
  {id:"β-VAE, Posterior Collapse & VQ-VAE", group:"dl", level:3, link:"deep-learning/autoencoders-vaes/beta-collapse-vqvae.html", desc:"What shapes a trained VAE: the reconstruction–KL trade-off read as rate and distortion and what β buys, posterior collapse and its remedies, traversal and holes in the latent space, the honest reasons samples blur, tighter bounds and richer posteriors, and VQ-VAE's discrete codebook."},
  {id:"Model Interpretability", group:"ml", level:2, desc:"Explaining what a fitted model is doing: intrinsic vs post-hoc methods, permutation importance, partial dependence and ICE curves, local surrogates, Shapley values and their additive attribution, saliency and class-activation maps for vision models, attention as an explanation and why that is contested, and the gap between an explanation that is faithful and one that is merely plausible."},
  {id:"Graph Neural Networks", group:"dl", level:2, link:"deep-learning/graph-neural-networks.html", desc:"Deep learning on graphs via neighbor message passing."},

  // NLP
  {id:"Tokenization", group:"nlp", level:2, link:"nlp/tokenization.html", desc:"Splitting text into sub-word units that models can consume."},
  {id:"Embeddings", group:"nlp", level:2, link:"nlp/embeddings.html", desc:"Dense vector representations where semantic similarity becomes geometric proximity."},
  {id:"Language Models", group:"nlp", level:2, link:"nlp/language-models.html", desc:"Models that predict the next token; scaled up, they become LLMs."},
  {id:"RAG", group:"nlp", level:2, link:"nlp/retrieval-augmented-generation.html", desc:"Retrieval-Augmented Generation — grounding LLM answers in retrieved documents."},
  {id:"Vision Models", group:"models", level:2, link:"models/vision-models.html", desc:"Image and video backbones and task models — convolutional (EfficientNet) and transformer-based (ViT family, DETR, SAM, DINOv2): what each architecture changed and how the families compare."},
  {id:"NLP Models", group:"models", level:2, link:"models/nlp-models.html", desc:"Encoder-only and encoder–decoder language models — BERT and its successors, T5, BART: pretraining objectives, input formats, and when an encoder or seq2seq model beats a decoder."},
  {id:"LLM Families", group:"models", level:2, link:"models/llm-families.html", desc:"Decoder-only large language model families — GPT, Llama, Mistral/Mixtral, Qwen, Gemma, DeepSeek: configs, attention variants (GQA, MLA, sliding window), MoE, and training recipes compared."},
  {id:"Audio Models", group:"models", level:2, link:"models/audio-models.html", desc:"Speech and audio models — Whisper and wav2vec 2.0: waveform/spectrogram front ends, self-supervised and weakly supervised pretraining, and CTC vs seq2seq decoding."},
  {id:"Multimodal Models", group:"models", level:2, link:"models/multimodal-models.html", desc:"Vision–language models — CLIP-style dual encoders and generative VLMs (LLaVA, BLIP-2, PaliGemma): how images are turned into tokens and aligned with language."},
  {id:"Document AI Models", group:"models", level:2, link:"models/document-ai-models.html", desc:"Models for visually rich documents — OCR-based LayoutLM and OCR-free Donut: layout as a modality, and pipeline vs end-to-end document understanding."},
  {id:"BERT", group:"models", level:3, link:"models/bert.html", desc:"Bidirectional encoder Transformer pretrained with masked language modeling — the pretrain-then-finetune workhorse for NLP understanding tasks."},

  {id:"BERT: Inputs, WordPiece & Encoder Stack", group:"models", level:4, link:"models/bert/inputs-encoder.html", desc:"The network BERT pretrains: how it differs from ELMo and GPT-1, why full bidirectional attention forces a masked objective, the packed [CLS]/[SEP] input summed from token, segment and position embeddings, the 30,522-entry WordPiece vocabulary, the post-LN GELU encoder block, Base and Large, and the parameter count recomputed from the configuration."},
  {id:"BERT: Masked-LM & NSP Pretraining", group:"models", level:4, link:"models/bert/pretraining.html", desc:"How BERT is pretrained: masked language modelling with the 15% and 80/10/10 rule worked by hand, what the released data generator actually does, next-sentence prediction and the conflicting ablations that led RoBERTa to drop it, the BooksCorpus and Wikipedia schedule with its 128 → 512 switch, and forward FLOPs per sequence."},
  {id:"BERT: Fine-Tuning, Probing & Results", group:"models", level:4, link:"models/bert/fine-tuning-results.html", desc:"Using and measuring a pretrained BERT: what the pooled [CLS] vector really is, the four task-head shapes, start/end span scoring with a no-answer threshold, the fine-tuning grid and its restart instability, frozen feature extraction, attention and probing analyses, the model-size ablation, and the GLUE, SQuAD and SWAG results."},
  {id:"BERT: RoBERTa, ELECTRA & Successors", group:"models", level:4, link:"models/bert/successors-practice.html", desc:"The encoder family after BERT and how to use it: ELECTRA's loss on every token, RoBERTa's longer training, ALBERT's parameter sharing, DistilBERT, DeBERTa and ModernBERT with the numbers behind each, BERT set against GPT and T5, Sentence-BERT bi-encoders for embeddings, and practical use through the Transformers library."},
  // Computer Vision
  {id:"Image Classification", group:"cv", level:2, desc:"Assigning a label to a whole image — the canonical vision task."},
  {id:"Object Detection", group:"cv", level:2, desc:"Locating and classifying multiple objects within an image (YOLO, Faster R-CNN)."},

  // MLOps
  {id:"Model Deployment", group:"mlops", level:2, desc:"Serving models behind APIs, batch jobs, or on-device."},
  {id:"Monitoring & Drift", group:"mlops", level:2, link:"mlops/monitoring-and-drift.html", desc:"Tracking live performance and detecting when data shifts away from training."},
  {id:"CI/CD", group:"mlops", level:2, desc:"Automated testing and deployment pipelines for code and models."},
  {id:"Experiment Tracking", group:"mlops", level:2, desc:"Logging runs, params, and metrics for reproducibility (MLflow, W&B)."},

  // Viz
  {id:"Dashboards", group:"viz", level:2, desc:"Interactive views that let stakeholders monitor metrics over time."},
  {id:"Data Storytelling", group:"viz", level:2, desc:"Framing analysis as a clear narrative aimed at a decision."},

  // LLMs & Generative AI
  {id:"Large Language Models", group:"llm", level:2, link:"llm/large-language-models.html", desc:"Transformer decoders scaled up on massive text via next-token prediction — yielding emergent in-context learning, instruction following, and reasoning."},
  {id:"Context Engineering", group:"llm", level:2, link:"llm/context-engineering.html", desc:"Designing what goes into the context window: prompting, few-shot examples, retrieved context, tools, and memory — feeding the model the right information at inference."},
  {id:"Parameter-Efficient Fine-Tuning", group:"llm", level:2, link:"llm/parameter-efficient-fine-tuning.html", desc:"Adapt a frozen pretrained model by training a tiny set of extra weights — LoRA, adapters, prefix/prompt tuning — instead of all parameters."},
  {id:"Policy / Preference Optimization", group:"llm", level:2, link:"llm/policy-preference-optimization.html", desc:"Align models to human preferences: RLHF (PPO) and direct methods (DPO, GRPO) that optimize a policy against a reward or preference signal."},
  {id:"LLM-as-a-Judge", group:"llm", level:2, link:"llm/llm-as-a-judge.html", desc:"Use a strong LLM to score or compare model outputs — scalable automated evaluation (autoraters), with care for bias, position effects, and calibration."},
  {id:"Diffusion LLMs", group:"llm", level:2, link:"llm/diffusion-llms.html", desc:"Generate text by iteratively denoising over discrete tokens rather than left-to-right — discrete/diffusion language models that can decode in parallel."},
  {id:"Vision-Language Models", group:"llm", level:2, link:"llm/vision-language-models.html", desc:"Multimodal models that jointly process images and text — a visual encoder bolted to an LLM for captioning, VQA, and grounded reasoning."},

  // Agentic AI
  {id:"Agents", group:"agent", level:2, link:"agentic/agents.html", desc:"LLMs that plan, call tools, and act in loops to accomplish goals — the move from single-shot answers to multi-step autonomy."},
  {id:"Agentic RL", group:"agent", level:2, link:"agentic/agentic-rl.html", desc:"Training agents with reinforcement learning over multi-step tool use and environment feedback — optimizing reward over trajectories, not single responses."},
  {id:"Agent Skills", group:"agent", level:2, link:"agentic/agent-skills.html", desc:"Reusable, composable capabilities an agent can invoke — packaged tools and procedures that extend what an agent can do."},
  {id:"Agentic Design Patterns", group:"agent", level:2, link:"agentic/agentic-design-patterns.html", desc:"Recurring architectures for agent systems — reflection, planning, tool use, and multi-agent collaboration."},

  // ===== curated expansion (substantial topics; micro-concepts live as sections of these) =====
  // Machine Learning
  {id:"Bias-Variance Tradeoff", group:"ml", level:2, link:"machine-learning/bias-variance-tradeoff.html", desc:"Why models under- or over-fit: test error splits into bias (too simple) and variance (too sensitive) — the classic U-curve and the modern double-descent twist."},
  {id:"Learning Paradigms", group:"ml", level:2, link:"machine-learning/learning-paradigms.html", desc:"The families of learning: supervised, unsupervised, self-supervised, semi-supervised, and reinforcement — what signal each learns from."},
  {id:"ML Algorithms Compared", group:"ml", level:2, link:"machine-learning/ml-algorithms-compared.html", desc:"A side-by-side of the classical algorithms — assumptions, decision boundaries, strengths, and when to reach for each."},
  {id:"ML Strategy", group:"ml", level:2, link:"machine-learning/ml-strategy.html", desc:"Andrew Ng's applied playbook (Machine Learning Yearning) for deciding what to work on next — dev/test set design, single-number metrics, error analysis, the avoidable-bias/variance/data-mismatch decomposition, learning curves, human-level performance, and the optimization verification test."},
  // Deep Learning
  {id:"Neural Network Training", group:"dl", level:2, link:"deep-learning/neural-network-training.html", desc:"How nets actually learn: backpropagation, loss functions, activation functions, weight initialization (Xavier), normalization (BatchNorm), dropout, and the batching/padding tricks that make it work."},
  {id:"Losses & Backpropagation", group:"dl", level:3, link:"deep-learning/neural-network-training/loss-backprop.html", desc:"Where the gradient comes from: the risk you want against the surrogate you minimise, the loss read from the optimiser's side, the computational graph, backpropagation derived and run on real numbers, reverse against forward mode and finite differences, and why it is a schedule rather than the chain rule."},
  {id:"Gradient Flow & Initialization", group:"dl", level:3, link:"deep-learning/neural-network-training/gradient-flow-init.html", desc:"Keeping signal alive through depth: vanishing and exploding gradients measured layer by layer, how each non-linearity's derivative gates gradient flow, the dying ReLU as an optimisation pathology, the variance argument behind initialisation, Xavier and He with their assumptions, and what ten-times mis-scaling does."},
  {id:"Gradient Descent & Optimizers", group:"dl", level:3, link:"deep-learning/neural-network-training/optimizers.html", desc:"Turning a gradient into a step: minibatch SGD, curvature and the condition number that cap the learning rate, saddles, plateaus and cliffs, moving averages with bias correction, then the optimiser family from momentum and Nesterov through AdaGrad, RMSProp and Adam to AdamW's decoupled decay."},
  {id:"LR Schedules, Batch Size & Precision", group:"dl", level:3, link:"deep-learning/neural-network-training/schedules-precision-memory.html", desc:"Making each step stable and affordable: learning-rate schedules and why warmup exists, the range test for choosing η, batch size with its memory arithmetic and coupling to the learning rate, mixed precision and loss scaling, and gradient accumulation with activation checkpointing."},
  {id:"Normalization Layers & Training Regularization", group:"dl", level:3, link:"deep-learning/neural-network-training/normalization-regularization.html", desc:"The layers and penalties that shape what training converges to: batch normalisation and its train/eval asymmetry, LayerNorm and RMSNorm with pre/post placement, the regularisation map, L2, L1 and weight decay, dropout as a cheap ensemble, early stopping, augmentation, noise injection and label smoothing."},
  {id:"Clipping, Tuning & Debugging Runs", group:"dl", level:3, link:"deep-learning/neural-network-training/tuning-debugging.html", desc:"Keeping a real run on the rails: gradient clipping that caps magnitude while keeping direction, which hyperparameters matter and why random search beats grid search, reading a training curve for the failure it encodes, and a systematic procedure for debugging a run that will not learn."},
  {id:"Fine-Tuning & Transfer Learning", group:"dl", level:2, link:"deep-learning/fine-tuning-transfer-learning.html", desc:"Reusing pretrained representations: feature generality by layer, feature extraction vs fine-tuning by data size × domain similarity, the freeze-then-unfreeze recipe and the BatchNorm trap, discriminative learning rates and gradual unfreezing, forgetting (L2-SP, EWC), LP-FT, domain adaptation, BERT and PEFT."},
  {id:"Knowledge Distillation", group:"dl", level:2, link:"deep-learning/knowledge-distillation.html", desc:"Train a small student to mimic a large teacher — compressing a model's behaviour into far fewer parameters."},
  {id:"Distributed Training", group:"dl", level:2, link:"deep-learning/distributed-training.html", desc:"Train models too big for one device: data, tensor, and pipeline parallelism, ZeRO sharding, plus gradient accumulation and checkpointing."},
  {id:"Data Parallelism, ZeRO & FSDP", group:"dl", level:3, link:"deep-learning/distributed-training/data-parallel-zero.html", desc:"Splitting the batch and then the model state: data parallelism with a gradient all-reduce, the sixteen bytes per parameter that mixed-precision Adam keeps on every GPU, ZeRO stages one to three and FSDP sharding optimiser state, gradients and parameters across ranks, and offloading to CPU memory and NVMe in exchange for bandwidth."},
  {id:"Collectives, Ring All-Reduce & DDP", group:"dl", level:3, link:"deep-learning/distributed-training/collectives-ddp.html", desc:"The traffic every parallel scheme pays for: the collectives — all-reduce, all-gather, reduce-scatter, all-to-all — and their latency and bandwidth cost, the ring all-reduce run step by step to show where 2·(n−1)/n · S comes from, and DDP in practice with one process per GPU, gradient buckets and accumulation."},
  {id:"Tensor, Sequence & Context Parallelism", group:"dl", level:3, link:"deep-learning/distributed-training/tensor-sequence-context.html", desc:"Splitting work inside a layer: Megatron's column- and row-parallel matmuls and why their activation-sized traffic keeps tensor parallelism inside a node, sequence parallelism for the norm and dropout regions it missed, and context parallelism for long sequences through ring attention or DeepSpeed-Ulysses head all-to-all."},
  {id:"Pipeline & Expert Parallelism", group:"dl", level:3, link:"deep-learning/distributed-training/pipeline-expert.html", desc:"Splitting the model by depth and by expert: pipeline stages fed with micro-batches and the bubble that idles them, the 1F1B, interleaved and zero-bubble schedules that trade activation memory against idle time, and expert parallelism's all-to-all dispatch and combine of routed tokens in mixture-of-experts layers."},
  {id:"N-D Parallelism, Planning & Checkpointing", group:"dl", level:3, link:"deep-learning/distributed-training/nd-parallelism-practice.html", desc:"Putting the axes together and keeping the run alive: composing data, tensor, pipeline and context degrees on a device mesh, choosing degrees for a 70 B model on 64 and 512 GPUs with the page's memory and traffic formulas, what Transformers and Accelerate support, and checkpointing sharded state for fault tolerance at scale."},
  {id:"Encoder vs Decoder Models", group:"dl", level:2, link:"deep-learning/encoder-decoder-models.html", desc:"Three Transformer wirings — encoder-only (BERT), decoder-only (GPT), and encoder-decoder (T5) — and which task each suits."},
  {id:"State Space Models", group:"dl", level:2, link:"deep-learning/state-space-models.html", desc:"Sequence models (S4, Mamba) that scale linearly with length via a learned recurrence — a sub-quadratic alternative to attention."},
  {id:"World Models & JEPA", group:"dl", level:2, link:"deep-learning/world-models-jepa.html", desc:"Models that learn predictive representations of how the world evolves — including JEPA, predicting in latent space rather than pixels."},
  {id:"DL Architectures Compared", group:"dl", level:2, link:"deep-learning/dl-architectures-compared.html", desc:"A map of the architecture zoo — MLPs, CNNs, RNNs, Transformers, SSMs — by inductive bias, cost, and the data each fits."},
  {id:"End-to-End Deep Learning", group:"dl", level:2, link:"deep-learning/end-to-end-learning.html", desc:"Replace a hand-engineered pipeline with a single network mapping raw input to output — when abundant (input→output) data makes it win, when a multi-stage pipeline is better, and how to choose pipeline components by data availability and task simplicity."},
  {id:"Classical Neural Networks", group:"dl", level:2, link:"deep-learning/classical-nn/index.html", desc:"The neural-network canon before (and beside) deep learning: perceptrons and the delta rule, Hopfield associative memory, Boltzmann machines and RBMs, Kohonen maps and competitive learning, RBF networks, neuro-fuzzy systems, Kalman-filter training, neural system identification and control, neuroevolution, and neural hardware — the ideas modern deep learning grew from or quietly reuses."},
  {id:"Perceptrons & Early Learning Rules", group:"dl", level:3, link:"deep-learning/classical-nn/perceptrons.html", desc:"The McCulloch–Pitts neuron, Hebbian learning, Rosenblatt's perceptron and its convergence theorem, Adaline and the LMS/delta rule, Madaline, and the linear-separability wall that XOR exposed."},
  {id:"Hopfield Networks & Associative Memory", group:"dl", level:3, link:"deep-learning/classical-nn/hopfield-associative-memory.html", desc:"Content-addressable memory: Hebbian outer-product storage, the Hopfield energy function and why asynchronous updates descend it, attractors and spurious states, the 0.138·N capacity limit, BAM, and the modern Hopfield network that turns out to be attention."},
  {id:"Boltzmann Machines & RBMs", group:"dl", level:3, link:"deep-learning/classical-nn/boltzmann-machines-rbms.html", desc:"Energy-based models: the Boltzmann distribution over binary units, the intractable partition function, the restricted bipartite RBM and block Gibbs sampling, contrastive divergence, and stacking RBMs into deep belief networks — the 2006 pretraining that restarted deep learning."},
  {id:"Self-Organizing Maps & Competitive Learning", group:"dl", level:3, link:"deep-learning/classical-nn/self-organizing-maps.html", desc:"Unsupervised winner-take-all learning: competitive layers, Kohonen's self-organizing map with its shrinking neighbourhood, topology preservation and the U-matrix, learning vector quantization, and adaptive resonance theory's answer to the stability–plasticity dilemma."},
  {id:"Radial Basis Function Networks", group:"dl", level:3, link:"deep-learning/classical-nn/rbf-networks.html", desc:"One hidden layer of localized Gaussian bumps plus a linear readout: centre selection by clustering, width heuristics, closed-form least-squares output weights, exact interpolation vs regularization networks, and how RBF nets relate to kernels, SVMs and GRNNs."},
  {id:"Neuro-Fuzzy Systems", group:"dl", level:3, link:"deep-learning/classical-nn/neuro-fuzzy.html", desc:"Fuzzy sets, membership functions and fuzzy if–then rules, Mamdani vs Takagi–Sugeno inference, and ANFIS — a fuzzy inference system laid out as a network whose premise and consequent parameters are trained by hybrid gradient/least-squares learning."},
  {id:"Kalman Filter Training", group:"dl", level:3, link:"deep-learning/classical-nn/kalman-filter-training.html", desc:"Treating network weights as the state of a dynamical system: the extended Kalman filter as a second-order training algorithm, global vs decoupled EKF, training recurrent networks, and the unscented filter — fast convergence at a quadratic memory price."},
  {id:"Neural System Identification & Control", group:"dl", level:3, link:"deep-learning/classical-nn/neural-system-identification.html", desc:"Networks as models of dynamical systems: NARX/NARMAX and series-parallel vs parallel identification, time-series prediction with tapped delay lines, and the classic neural control architectures — model-reference, NARMA-L2, model predictive and inverse control."},
  {id:"Neuroevolution & Growing Networks", group:"dl", level:3, link:"deep-learning/classical-nn/neuroevolution.html", desc:"Searching over network weights and architectures with evolution: direct vs developmental encodings, NEAT's speciation and historical markings, HyperNEAT and CPPNs, constructive nets like cascade-correlation, pruning, and the link to modern architecture search."},
  {id:"Neural Network Hardware", group:"dl", level:3, link:"deep-learning/classical-nn/neural-hardware.html", desc:"Running networks on silicon: fixed-point and low-precision arithmetic, approximating sigmoid/tanh in hardware, MAC arrays and systolic dataflows, FPGA design trade-offs (parallelism vs area vs precision), on-chip learning, and why GPUs/TPUs won the general case."},
  {id:"Deep Learning in Practice", group:"dl", level:2, link:"deep-learning/dl-in-practice.html", desc:"From idea to a trained model with a real framework: tensors and autodiff, eager vs graph execution, Keras' Sequential/Functional/subclassing APIs vs PyTorch modules, input pipelines, the training loop and callbacks, the fastai-style recipe (LR finder, one-cycle, progressive unfreezing), debugging and reproducibility."},
  // NLP
  {id:"Text Preprocessing", group:"nlp", level:2, link:"nlp/text-preprocessing.html", desc:"Getting raw text model-ready: cleaning, normalization, casing, stop-words, stemming/lemmatization, and where modern sub-word pipelines differ."},
  {id:"Named Entity Recognition", group:"nlp", level:2, link:"nlp/named-entity-recognition.html", desc:"Tagging spans of text as entities (people, places, orgs) — sequence labeling with BIO schemes."},
  {id:"Machine Translation", group:"nlp", level:2, link:"nlp/machine-translation.html", desc:"Mapping text between languages — from alignment-based statistical MT to attention-based neural MT and multilingual LLMs."},
  {id:"Textual Entailment", group:"nlp", level:2, link:"nlp/textual-entailment.html", desc:"Natural Language Inference: does a premise entail, contradict, or stay neutral toward a hypothesis?"},
  {id:"Document Intelligence", group:"nlp", level:2, link:"nlp/document-intelligence.html", desc:"Extracting structure and answers from documents — layout, tables, and figures in PDFs and scans, often multimodal."},
  {id:"Knowledge Graphs", group:"nlp", level:2, link:"nlp/knowledge-graphs.html", desc:"Representing facts as entities and typed relations — construction, embeddings, and use as structured grounding for retrieval and reasoning."},
  // Data Engineering
  {id:"Data Preprocessing", group:"deng", level:2, link:"data-engineering/data-preprocessing.html", desc:"Turning raw features model-ready: standardization vs normalization, scaling, encoding categoricals, and handling missing values."},
  {id:"Data Sampling & Imbalance", group:"deng", level:2, link:"data-engineering/data-sampling-imbalance.html", desc:"Building representative, balanced training sets — sampling strategies, class imbalance, over/under-sampling and SMOTE."},
  {id:"Data Quality & Governance", group:"deng", level:2, link:"data-engineering/data-quality-governance.html", desc:"Trustworthy data: filtering and deduplication, label quality and inter-annotator agreement, and PII handling/privacy."},
  {id:"Vector Databases (HNSW)", group:"dsys", level:2, link:"databases/vector-databases.html", desc:"The retrieval layer for semantic search and RAG — approximate nearest-neighbor (ANN) search over embedding vectors. HNSW (Hierarchical Navigable Small World) layered proximity graphs, the M/efConstruction/efSearch knobs, recall↔speed↔memory trade-offs, and how it compares to flat and IVF indexes."},
  // MLOps
  {id:"LLMOps", group:"mlops", level:2, link:"mlops/llmops.html", desc:"Operating LLM apps in production — prompt/version management, evaluation, guardrails, caching, and cost/latency monitoring."},
  {id:"Model Acceleration", group:"mlops", level:2, link:"mlops/model-acceleration.html", desc:"Serve models faster and cheaper — quantization, pruning, compilation, and speculative decoding."},
  {id:"Speculative Decoding", group:"mlops", level:2, link:"mlops/speculative-decoding.html", desc:"Speed up autoregressive decoding losslessly: a small draft model proposes several tokens that the large target model verifies in one parallel pass, with a modified rejection-sampling rule that provably preserves the target's output distribution. Covers the acceptance-rate/speedup math and variants (self-speculative, Medusa, EAGLE, lookahead)."},
  // LLMs & Generative AI
  {id:"Reasoning in LLMs", group:"llm", level:2, link:"llm/reasoning-in-llms.html", desc:"Eliciting multi-step thinking — chain-of-thought, self-consistency, tree/graph-of-thought, and reasoning-trained models."},
  {id:"Hallucination & Factuality", group:"llm", level:2, link:"llm/hallucination-factuality.html", desc:"Why LLMs fabricate and how to catch it — measuring factuality, detecting hallucinations, and grounding/abstention mitigations."},
  {id:"Context-Length Extension", group:"llm", level:2, link:"llm/context-length-extension.html", desc:"Pushing the context window longer — positional interpolation, RoPE scaling, and efficient long-context attention."},
  {id:"GPT", group:"models", level:3, link:"models/gpt.html", desc:"Generative Pre-trained Transformer — the decoder-only autoregressive lineage (GPT-1→4) behind modern LLMs; the generative counterpart to BERT."},
  {id:"GPT: Autoregressive Objective & Causal Masking", group:"models", level:4, link:"models/gpt/autoregressive-objective.html", desc:"The single objective every GPT shares: why generative pretraining replaced per-task training, the five-step lineage, the chain-rule factorisation into left-to-right conditionals, next-token cross-entropy and perplexity worked by hand, the causal mask that makes training parallel and generation sequential, and the sampling loop step by step."},
  {id:"GPT: Decoder Block, Configs & Training Data", group:"models", level:4, link:"models/gpt/decoder-scale.html", desc:"The network and what it costs: the decoder block without cross-attention, GPT-2's move to pre-LN with a scaled residual initialisation, byte-pair tokenisation across generations, every published configuration, parameter counts from 12·L·d² + V·d, compute from 2N and 6ND FLOPs, and each generation's training-data mixture."},
  {id:"GPT: GPT-1 to GPT-3 & In-Context Learning", group:"models", level:4, link:"models/gpt/gpt1-to-gpt3.html", desc:"How the generations used the same objective differently: GPT-1's fine-tuning with input transformations, GPT-2's zero-shot tasks written as text, GPT-3's training and few-shot prompting, its eight-size sweep, failure cases and contamination analysis, then in-context learning, the emergence debate and the scaling laws around them."},
  {id:"GPT: Decoding, InstructGPT & GPT-4", group:"models", level:4, link:"models/gpt/decoding-successors.html", desc:"Running GPT models and what followed them: greedy, beam, temperature, top-k, top-p and repetition-penalty decoding, the KV cache with prefill and decode phases, InstructGPT's three-stage path to instruction following, what the GPT-4 report states and withholds, open reproductions, and the comparison with BERT and encoder–decoders."},
  {id:"CLIP", group:"models", level:3, link:"models/clip.html", desc:"Contrastive Language-Image Pre-training — dual image/text encoders aligned in a shared embedding space; zero-shot vision and the backbone of text-to-image models."},
  {id:"CLIP: Contrastive Pretraining", group:"models", level:4, link:"models/clip/contrastive-pretraining.html", desc:"The objective that defines CLIP: why learn vision from language, two towers that never attend to each other, the symmetric cross-entropy over an N × N similarity matrix worked by hand, its probability-minus-target gradient, the learned logit scale, the batch as the negative set, and sharded similarity computation."},
  {id:"CLIP: Data, Encoders & Training", group:"models", level:4, link:"models/clip/data-encoders.html", desc:"What the loss is applied to: the 400M-pair WIT dataset built from 500,000 queries capped at 20,000 pairs each, why contrastive beat caption prediction, the modified ResNet and ViT image towers, the 63M-parameter BPE text Transformer, linear projection with L2 normalisation, and the 32-epoch training recipe."},
  {id:"CLIP: Zero-Shot Transfer & Robustness", group:"models", level:4, link:"models/clip/zero-shot-evaluation.html", desc:"Using the trained space as a classifier: class-name sentences embedded into a linear head, prompt templates and ensembling, results over 27 datasets, zero-shot against few-shot and linear probes, robustness under ImageNet distribution shifts and how adaptation erodes it, and the train–test data-overlap analysis."},
  {id:"CLIP: Limitations, Geometry & Downstream Use", group:"models", level:4, link:"models/clip/limits-downstream.html", desc:"Where CLIP falls short and where it is reused: the paper's limitations grouped by task, representation and evaluation, bias from class design and web data, the modality gap between image and text cones, retrieval and CLIPScore, guiding and conditioning text-to-image generators, and serving as a VLM vision tower."},
  {id:"CLIP: ALIGN, LiT, SigLIP & Successors", group:"models", level:4, link:"models/clip/successors.html", desc:"The dual-encoder family after CLIP and how to use it: ALIGN on noisy alt-text, LiT's locked image tower, OpenCLIP on LAION with reproducible scaling laws, SigLIP's pairwise sigmoid loss, data-curation successors, and the preprocessing, tokenisation and logit-scale details that practical use depends on."},
  {id:"LayoutLM", group:"models", level:3, link:"models/layoutlm.html", desc:"The Document-AI family (v1→v2→v3) that fuses text, 2D layout (OCR bounding boxes), and image in one Transformer for visually-rich document understanding — forms, receipts, invoices, doc classification, and document VQA."},
  {id:"LayoutLM: OCR Inputs, 2-D Positions & v1", group:"models", level:4, link:"models/layoutlm/inputs-v1.html", desc:"The input LayoutLM reads and the first model that read it: why position on the page carries meaning, the document-understanding tasks and datasets, OCR words, boxes and reading order, scaling boxes to a 0–1000 grid, v1's 2-D position embeddings from X and Y tables, sub-word boxes, masked visual-language modelling, fine-tuning-only image features, and v1 results."},
  {id:"LayoutLM: v2 Spatial Attention & LayoutXLM", group:"models", level:4, link:"models/layoutlm/v2-layoutxlm.html", desc:"LayoutLMv2 and its multilingual sibling: text and 49 visual tokens from a ResNeXt-101-FPN backbone in one sequence, the six-part layout embedding, spatial-aware self-attention with learned relative 1-D and 2-D biases, text–image alignment and matching added to masked prediction, configurations and results, and LayoutXLM across 53 languages with XFUND."},
  {id:"LayoutLM: v3 Patches, Parameters & Benchmarks", group:"models", level:4, link:"models/layoutlm/v3-benchmarks.html", desc:"LayoutLMv3 and the family's numbers: the CNN replaced by linearly embedded 16 × 16 patches, masked language and masked image modelling made symmetric with word–patch alignment, v3 configurations, recipes and results, parameter counts recomputed from every released configuration, and one benchmark chart across all four members with its settings."},
  {id:"LayoutLM: Fine-Tuning, Relatives & Practice", group:"models", level:4, link:"models/layoutlm/fine-tuning-practice.html", desc:"Putting the family to work: per-task fine-tuning heads for extraction, QA and classification, input construction within the 512-position text budget and long documents, a design comparison of v1, v2, LayoutXLM and v3, relatives such as MarkupLM, LiLT and LayoutReader, the OCR-free alternative, and code and weight licences."},
  {id:"Donut", group:"models", level:3, link:"models/donut.html", desc:"OCR-free Document Understanding Transformer — a Swin vision encoder + BART-style decoder that reads document pixels and generates structured output (JSON) directly, no OCR. Pretrained with SynthDoG; DONUT-hole distills/prunes it for the edge."},
  {id:"Donut: OCR-Free Design & Swin Encoder", group:"models", level:4, link:"models/donut/ocr-free-encoder.html", desc:"Why Donut removes the OCR stage and how the page enters the model: the two-stage pipeline it replaces, its six datasets across classification, extraction and DocVQA, the encoder–decoder at a glance, fitting each page onto a fixed canvas, the modified Swin-B encoder, and shifted-window attention."},
  {id:"Donut: Decoder, Prompts & JSON Tokens", group:"models", level:4, link:"models/donut/decoder-output.html", desc:"How Donut writes its answer: the four-layer mBART-style decoder initialised from asian-bart, cross-attention over 4,800 encoder vectors as the only path from pixels to text, the 143M and 176M parameter counts recomputed, task-prompt start tokens, and the recursive JSON-to-token serialisation."},
  {id:"Donut: Pretraining, SynthDoG & Fine-Tuning", group:"models", level:4, link:"models/donut/training.html", desc:"One loss for every stage of Donut's training: next-token negative log-likelihood under teacher forcing, pretraining as pseudo-OCR that reads a page top-left to bottom-right, SynthDoG's layered synthetic document renderer, and the per-task canvas, output-length, schedule and special-token choices of fine-tuning."},
  {id:"Donut: Evaluation, Ablations & Limits", group:"models", level:4, link:"models/donut/evaluation-limits.html", desc:"Measuring Donut: field-level F1 against tree-edit-distance accuracy, results and timings against OCR-based baselines, ablations of backbone, canvas resolution and OCR engine, its handwritten DocVQA advantage despite a lower overall score, and the limits of a fixed canvas, single page and generative decoder."},
  {id:"Donut: DONUT-hole, Relatives & Practice", group:"models", level:4, link:"models/donut/variants-relatives.html", desc:"Donut among its descendants and rivals: DONUT-hole's pruning and knowledge distillation, CKA for comparing layer representations, image-to-text relatives such as Dessurt, Pix2Struct and Nougat, the OCR-based LayoutLM strand set against it, and practical use through VisionEncoderDecoderModel and DonutProcessor."},
  {id:"EfficientNet", group:"models", level:3, link:"models/efficientnet.html", desc:"Compound model scaling for ConvNets: grow depth, width and input resolution together (d = αᵠ, w = βᵠ, r = γᵠ, α·β²·γ² ≈ 2) from a NAS-found MBConv + squeeze-and-excitation baseline (B0), giving the B0–B7 family, plus its FLOPs-vs-latency critiques and the EfficientNetV2 follow-up."},
  {id:"EfficientNet: The Scaling Problem", group:"models", level:4, link:"models/efficientnet/scaling-problem.html", desc:"Why scaling a ConvNet needed a rule: one-axis scaling of deeper ResNets, wider nets or larger inputs, the paper's stage-wise formulation that fixes layer types, the cost formula behind FLOPs ∝ d·w²·r², why each axis saturates near 80%, and why the axes interact."},
  {id:"EfficientNet: Compound Scaling", group:"models", level:4, link:"models/efficientnet/compound-scaling.html", desc:"The compound scaling rule itself: depth, width and resolution grown geometrically in one exponent φ, the grid search on B0 that fixes α = 1.2, β = 1.1, γ = 1.15 under α·β²·γ² ≈ 2, the φ the paper never lists, the hard-coded B0–B7 configs, and channel and repeat rounding."},
  {id:"EfficientNet: B0, MBConv & Training Recipe", group:"models", level:4, link:"models/efficientnet/b0-mbconv.html", desc:"The network that gets scaled: the MnasNet-style search that found B0, its stem, seven MBConv stages and head, the 5.29 M parameters and 0.39 B FLOPs recounted, the mobile inverted bottleneck and its cost, squeeze-and-excitation, Swish/SiLU, and the RMSProp, stochastic-depth training recipe."},
  {id:"EfficientNet: Results, Transfer & Latency", group:"models", level:4, link:"models/efficientnet/results.html", desc:"The paper's evidence re-checked: ImageNet parameter and FLOP ratios recomputed from Table 2, compound scaling applied to MobileNets and ResNet, single-core CPU latency, eight transfer datasets, scaling separated from architecture, validation against test-server accuracy, and why low FLOPs do not mean low GPU latency."},
  {id:"EfficientNet: V2, Critiques & Descendants", group:"models", level:4, link:"models/efficientnet/successors.html", desc:"What came after and how to use it: EfficientNetV2 optimising training speed and parameters, the FixRes train–test resolution discrepancy, critiques that separate the scaling rule from the training recipe, Lite, EfficientDet and Noisy Student descendants, the paper's internal inconsistencies, and practical backbone use."},
  {id:"T5", group:"models", level:3, link:"models/t5.html", desc:"Text-to-Text Transfer Transformer — an encoder–decoder that casts every NLP task as string-to-string, pretrained with span corruption on C4, plus the systematic study of architectures, objectives, data and scaling behind it and its successors (v1.1, mT5, ByT5, Flan-T5, UL2)."},
  {id:"T5: Text-to-Text Format & Architecture", group:"models", level:4, link:"models/t5/text-to-text-architecture.html", desc:"The model T5 trains: every task cast as a prefixed input string and a target string, the encoder–decoder with bias-free RMS-style pre-norm, 32 log-spaced relative-position buckets, unscaled attention offset by initialisation, the ReLU and GEGLU feed-forward layers, the five configurations, and parameter counts recomputed from them."},
  {id:"T5: C4, SentencePiece & Span Corruption", group:"models", level:4, link:"models/t5/c4-span-corruption.html", desc:"What T5 is pretrained on and how: the 32,000-piece SentencePiece vocabulary with 100 sentinel tokens, the Colossal Clean Crawled Corpus and its line- and page-level filters, span corruption with sentinels worked by hand, and the length arithmetic that turns 568 raw tokens into 512 inputs and 114 targets."},
  {id:"T5: Transfer Study, Recipe & Results", group:"models", level:4, link:"models/t5/study-recipe-results.html", desc:"The controlled comparison behind T5: a fixed baseline varied one factor at a time across architectures and mask patterns, denoising objectives and span lengths, pretraining corpora and repetition, fine-tuning and multi-task mixing strategies, and uses of extra compute, then the Adafactor schedule, the final recipe and the five sizes' test-set results."},
  {id:"T5: v1.1, mT5, Flan-T5 & Successors", group:"models", level:4, link:"models/t5/successors-practice.html", desc:"The T5 family and its practical use: the cleaned-up v1.1 checkpoints, multilingual mT5, byte-level ByT5, instruction-tuned Flan-T5, UL2's mixture of denoisers, T5Gemma adapted from decoder-only weights, the compute arithmetic of encoder–decoder against decoder-only models, and loading and generating with the Transformers library."},
  {id:"Whisper", group:"models", level:3, link:"models/whisper.html", desc:"Whisper — OpenAI's log-mel Transformer encoder–decoder trained on 680,000 hours of weakly supervised web audio: special-token task format, 20 ms timestamp tokens, sizes from tiny to large-v3 and turbo, zero-shot robustness, and long-form decoding with temperature fallback."},
  {id:"Whisper: Weak-Supervision Data & Architecture", group:"models", level:4, link:"models/whisper/data-architecture.html", desc:"What Whisper learns from and the network that learns it: the case for weakly supervised recognition over self-supervised encoders, the 680,000-hour multilingual dataset and its transcript-quality filters, the 16 kHz log-mel front end, fixed 30-second windows with a convolution stem, the sinusoidal pre-LN encoder and the cross-attending GPT-2-style decoder."},
  {id:"Whisper: Multitask Tokens, Sizes & Training", group:"models", level:4, link:"models/whisper/tokens-training.html", desc:"How one decoder does every task and how it was trained: the byte-level BPE vocabularies, the multitask grammar of language, task and timestamp tokens, timestamps as relative-time tokens, the logit filters that constrain decoding, five sizes recounted from the checkpoints, where per-window compute goes, the AdamW schedule, and multitask transfer."},
  {id:"Whisper: WER, Robustness & Multilingual Results", group:"models", level:4, link:"models/whisper/evaluation-robustness.html", desc:"Measuring Whisper: word error rate as normalised word-level edit distance, effective robustness across English datasets beyond LibriSpeech, multilingual recognition and its scaling with hours of training data per language, zero-shot speech translation and language identification, and behaviour under additive noise and on long recordings."},
  {id:"Whisper: Long-Form Decoding, Releases & Practice", group:"models", level:4, link:"models/whisper/longform-practice.html", desc:"Running Whisper on real audio: sequential and chunked long-form transcription, the beam search, temperature-fallback and compression-ratio heuristics that keep it from looping, the large-v2, large-v3 and turbo releases, Distil-Whisper with speculative decoding, hallucination and other limits, and use through the Transformers library."},
  {id:"Llama", group:"models", level:3, link:"models/llama.html", desc:"Meta's open-weight decoder family (LLaMA → Llama 2 → Llama 3/3.1/3.2/3.3 → Llama 4): the RMSNorm/SwiGLU/RoPE bias-free block, training small models far past compute-optimal, GQA, the 128K vocabulary and 128K context via RoPE base 500k and llama3 scaling, Llama 2-Chat's RLHF and Ghost Attention, Llama 4's MoE and interleaved NoPE layers — with every config's parameters, KV cache and compute recomputed."},

  {id:"Llama: LLaMA 1 Recipe & the Decoder Block", group:"models", level:4, link:"models/llama/recipe-block.html", desc:"The recipe LLaMA 1 set and the block every Llama shares: seven releases at a glance, training small models on public data far past compute-optimal for cheaper inference, data and tokenizers by generation, and the four deltas from GPT — pre-norm RMSNorm, SwiGLU at (2/3)·4d, RoPE worked by hand, no biases — plus the optimiser settings."},
  {id:"Llama: GQA, Configurations & Compute", group:"models", level:4, link:"models/llama/gqa-configs.html", desc:"What Llama 2 changed and what each release costs: longer pretraining and context, grouped-query attention sharing key and value heads across query groups, every released configuration, parameter counts that differ from GPT's 12·L·d², KV-cache bytes per token for each model, and 6·N·D training compute checked against reported GPU-hours."},
  {id:"Llama: Chat RLHF, Long Context & Llama 4", group:"models", level:4, link:"models/llama/post-training-generations.html", desc:"From base model to assistant and on through the later releases: Llama 2-Chat's supervised fine-tuning with separate helpfulness and safety reward models, rejection sampling followed by PPO, context extension from 8K to 128K through RoPE base and rescaling, Llama 3 to 3.3, Llama 4's mixture of experts with interleaved NoPE, and Ghost Attention."},
  {id:"Llama: Licence, Ecosystem & Practice", group:"models", level:4, link:"models/llama/ecosystem-practice.html", desc:"Llama as a released artefact: what the community licence does and does not open, the ecosystem that grew from the weights — Alpaca, Vicuna, Code Llama and quantised GGUF builds — loading and prompting the models through the Transformers library with the right chat template, and a design comparison against GPT-3 and later peers."},
  // ===== aman-coverage additions (curated gaps) =====
  {id:"Speech & Audio", group:"speech", level:1, desc:"Processing and generating audio and speech — features, recognition, and synthesis across the audio modality."},
  {id:"Speech Processing", group:"speech", level:2, link:"speech/speech-processing.html", desc:"Turning audio into text and back — spectrogram features, automatic speech recognition (ASR), text-to-speech (TTS), and audio representation learning."},
  {id:"Hyperparameter Tuning", group:"ml", level:2, link:"machine-learning/hyperparameter-tuning.html", desc:"Searching for good settings (learning rate, depth, regularization) — grid/random search, Bayesian optimization, and early-stopping schemes like Hyperband."},
  {id:"Residual / Skip Connections", group:"dl", level:2, link:"deep-learning/residual-skip-connections.html", desc:"y = x + F(x): the degradation problem, identity-mapping and gradient-highway arguments, the ensemble-of-paths view, bottleneck/pre-activation/ResNeXt/DenseNet blocks, highway gates, U-Net long skips, the Transformer residual stream, stochastic depth and zero-init tricks."},
  {id:"Hidden Markov Models & CRFs", group:"nlp", level:2, link:"nlp/hidden-markov-models-crfs.html", desc:"Probabilistic sequence models for labeling — HMMs, MEMMs, and Conditional Random Fields that score whole label sequences (classic NER/tagging)."},
  {id:"Text Classification", group:"nlp", level:2, link:"nlp/text-classification.html", desc:"Assigning labels to text — binary/multi-class/multi-label schemes, BoW/TF-IDF and fine-tuned-encoder pipelines, sentiment & aspect-based sentiment, class imbalance, and precision/recall/F1 evaluation."},
  {id:"Text Summarization", group:"nlp", level:2, link:"nlp/text-summarization.html", desc:"Compressing documents — extractive (TextRank/centroid sentence ranking) vs abstractive (seq2seq/LLM) summaries, faithfulness & hallucination, and ROUGE evaluation."},
  {id:"Question Answering", group:"nlp", level:2, link:"nlp/question-answering.html", desc:"Answering questions over text — extractive span prediction (SQuAD), open-domain retriever-reader, generative/closed-book QA, answerability/abstention, and EM/F1 evaluation."},
  {id:"NLP Evaluation Metrics", group:"nlp", level:2, link:"nlp/evaluation-metrics.html", desc:"The canonical hub for scoring generated text — n-gram overlap (BLEU, ROUGE, METEOR, chrF), embedding-based (BERTScore, MoverScore), perplexity, and LLM-as-a-Judge with its failure modes."},
  {id:"Computer Control", group:"agent", level:2, link:"agentic/computer-control.html", desc:"Agents that operate a computer — clicking, typing, and navigating GUIs and browsers from screenshots to complete real-world tasks."},
  {id:"A/B Testing", group:"mlops", level:2, link:"mlops/ab-testing.html", desc:"Online evaluation by randomized experiment — split traffic, compare metrics, and test for statistically significant lift."},
  {id:"Federated Learning", group:"mlops", level:2, link:"mlops/federated-learning.html", desc:"Train across many devices or silos without centralizing data — local updates aggregated into a shared model, for privacy and edge settings."},
  {id:"Differential Privacy", group:"deng", level:2, link:"data-engineering/differential-privacy.html", desc:"A formal privacy guarantee — add calibrated noise so outputs barely change when any single record is added or removed, bounding information leakage."},
  {id:"Contrastive Learning", group:"dl", level:2, link:"deep-learning/contrastive-learning.html", desc:"Learn representations by pulling positive pairs together and pushing negatives — especially hard negatives — apart. The InfoNCE/NT-Xent objective behind SimCLR, MoCo, and CLIP-style multimodal embeddings."},
  {id:"Vision Transformers", group:"cv", level:2, link:"vision/vision-transformers.html", desc:"Apply the Transformer directly to images: split a picture into fixed-size patches, linearly embed them as a token sequence (plus a [CLS] token and positional embeddings), and run a standard encoder. At scale ViT matches or beats CNNs — the backbone behind CLIP, modern detectors/segmenters, and most vision-language models."},
];

